// Package nftgen1 is the second generation of the fully on-chain
// generative engine. Same contract as nftgen0 - pure functions, seed in,
// traits and SVG out, no IPFS and no off-chain renderer - but it fixes
// the three weaknesses that offline simulation found in gen0 at a
// 1000-token supply (scripts/gen-sim.py, scripts/gen1-proposal-sim.py):
//
//  1. TRAIT SPACE. gen0 has 7.200 possible combinations, so a 1000-token
//     drop lands 112 tokens (11,2%) on a combination somebody else also
//     has, worst case four identical trait sets. gen1 has 1.254.400
//     combinations: two new layers (Frame, Finish), wider Palette/Shape/
//     Ground tables and wider Elements/Symmetry ranges.
//
//  2. RARITY. In gen0 the tier is decided by Aura plus Elements>=11 and
//     nothing else, so Palette/Shape/Ground carry zero rarity signal and
//     the only visible "rare" cue is one ring. gen1 scores EVERY trait
//     and derives the tier from the total, which is why a Prism palette
//     or an Ornate frame is worth something on its own.
//
//  3. SNIPING. gen0's seed is exactly "<collectionID>:<tokenID>", so
//     anybody can compute the whole rarity map before the first mint and
//     wait for a good ID to come up in the sequential queue. gen1 seeds
//     accept a per-collection SALT (SeedForSalted). A collection that is
//     created with an unpredictable salt has an unpredictable rarity map
//     until the salt is public, while determinism is untouched: the salt
//     is fixed at collection creation and never changes, so a token's
//     artwork is still identical on every node, forever.
//
// WHY THIS IS A NEW REALM AND NOT AN EDIT
//
// Gno realms are immutable and nft56 pins its engine at COMPILE time
// (`import "gno.land/r/.../nftgen0"` plus `const Engine`). Deploying
// nftgen1 therefore does nothing on its own - it needs a new NFT realm
// family (nft57) that imports it. That is deliberate: tokens already
// minted from gen0 must keep rendering exactly as they do today.
package nftgen1

import (
	"encoding/base64"
	"strconv"
	"strings"

	"gno.land/p/nt/ufmt/v0"
)

// ---------------------------------------------------------------------
// Deterministic randomness - byte-for-byte the gen0 stream.
//
// FNV-1a over the seed, then a splitmix64 mixer. Pure integer math: no
// floats, no time, no block data. The offline simulators port this exact
// arithmetic, so the distribution numbers quoted above are the numbers
// this code produces.
// ---------------------------------------------------------------------

const (
	fnvOffset uint64 = 14695981039346656037
	fnvPrime  uint64 = 1099511628211
)

type rng struct {
	state uint64
}

func newRNG(seed string) *rng {
	h := fnvOffset
	for i := 0; i < len(seed); i++ {
		h ^= uint64(seed[i])
		h *= fnvPrime
	}
	if h == 0 {
		h = fnvPrime
	}
	return &rng{state: h}
}

func (r *rng) next() uint64 {
	r.state += 0x9E3779B97F4A7C15
	z := r.state
	z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9
	z = (z ^ (z >> 27)) * 0x94D049BB133111EB
	return z ^ (z >> 31)
}

// intn returns a value in [0, n).
func (r *rng) intn(n int) int {
	if n <= 0 {
		return 0
	}
	return int(r.next() % uint64(n))
}

// ---------------------------------------------------------------------
// Weighted trait tables
//
// gen0 expressed weights by repeating entries inside a uniform table,
// which cannot express "4%" without a 25-entry slice. Here the weight is
// explicit and a single draw walks the cumulative sum, so a trait can be
// genuinely scarce and the tables stay readable.
// ---------------------------------------------------------------------

type option struct {
	name   string
	weight int
	score  int // contribution to the rarity score
}

func pick(r *rng, table []option) option {
	total := 0
	for _, o := range table {
		total += o.weight
	}
	roll := r.intn(total)
	acc := 0
	for _, o := range table {
		acc += o.weight
		if roll < acc {
			return o
		}
	}
	return table[len(table)-1]
}

type palette struct {
	option
	bg  string
	ink string
	c1  string
	c2  string
	c3  string
}

// Palette weights sum to 100, so a weight reads directly as a percent.
var palettes = []palette{
	{option{"Emerald", 18, 0}, "#04140f", "#7cf2c4", "#10b981", "#34d399", "#065f46"},
	{option{"Amethyst", 18, 0}, "#0b0713", "#e9d5ff", "#8b5cf6", "#c084fc", "#4c1d95"},
	{option{"Abyss", 16, 0}, "#02101c", "#bae6fd", "#0ea5e9", "#38bdf8", "#0c4a6e"},
	{option{"Ember", 14, 0}, "#160806", "#fecaca", "#f97316", "#fb923c", "#7c2d12"},
	{option{"Bone", 12, 0}, "#f5f5f4", "#1c1917", "#78716c", "#a8a29e", "#292524"},
	{option{"Solar", 10, 0}, "#1a1403", "#fef08a", "#eab308", "#facc15", "#713f12"},
	{option{"Obsidian", 8, 2}, "#050505", "#e5e5e5", "#404040", "#737373", "#171717"},
	{option{"Prism", 4, 4}, "#0a0a12", "#fdf4ff", "#22d3ee", "#f472b6", "#a78bfa"},
}

var shapes = []option{
	{"Orbit", 20, 0},
	{"Lattice", 18, 0},
	{"Bloom", 18, 0},
	{"Shard", 16, 0},
	{"Spiral", 14, 0},
	{"Weave", 9, 2},
	{"Rift", 5, 4},
}

var grounds = []option{
	{"Flat", 30, 0},
	{"Halo", 25, 0},
	{"Grid", 22, 0},
	{"Rings", 14, 1},
	{"Scatter", 9, 2},
}

var frames = []option{
	{"None", 55, 0},
	{"Thin", 25, 1},
	{"Double", 14, 2},
	{"Ornate", 6, 4},
}

var finishes = []option{
	{"Matte", 50, 0},
	{"Gloss", 28, 1},
	{"Glow", 16, 2},
	{"Foil", 6, 4},
}

var auras = []option{
	{"None", 78, 0},
	{"Soft", 14, 2},
	{"Bright", 6, 4},
	{"Nova", 2, 7},
}

// Traits are the decoded, human readable properties of a seed. The SVG
// builder and the trait string both read this one struct, so the picture
// and the metadata can never describe different artwork.
type Traits struct {
	Palette  string
	Shape    string
	Ground   string
	Frame    string
	Finish   string
	Aura     string
	Elements int
	Symmetry int
	Score    int
	Rarity   string
}

// Tier cut-offs. Chosen on the 1000-seed simulation, which gives
// Common 21,4% / Uncommon 44,4% / Rare 25,2% / Legendary 7,6% /
// Mythic 1,4% - a top segment wide enough to matter and narrow enough
// to stay special.
const (
	scoreMythic    = 12
	scoreLegendary = 8
	scoreRare      = 5
	scoreUncommon  = 2
)

func derive(seed string) (Traits, palette) {
	r := newRNG(seed)

	// Draw order is part of the contract: changing it changes every
	// token's artwork, so it must match the simulators exactly.
	p := palettes[0]
	{
		total := 0
		for _, q := range palettes {
			total += q.weight
		}
		roll := r.intn(total)
		acc := 0
		for _, q := range palettes {
			acc += q.weight
			if roll < acc {
				p = q
				break
			}
		}
	}
	shape := pick(r, shapes)
	ground := pick(r, grounds)
	frame := pick(r, frames)
	finish := pick(r, finishes)
	aura := pick(r, auras)

	t := Traits{
		Palette:  p.name,
		Shape:    shape.name,
		Ground:   ground.name,
		Frame:    frame.name,
		Finish:   finish.name,
		Aura:     aura.name,
		Elements: 5 + r.intn(10), // 5..14
		Symmetry: 2 + r.intn(7),  // 2..8
	}

	// Rarity is a score over every trait, not a single visible flag.
	score := p.score + shape.score + ground.score + frame.score + finish.score + aura.score
	if t.Elements >= 13 {
		score++
	}
	if t.Symmetry >= 7 {
		score++
	}
	t.Score = score

	switch {
	case score >= scoreMythic:
		t.Rarity = "Mythic"
	case score >= scoreLegendary:
		t.Rarity = "Legendary"
	case score >= scoreRare:
		t.Rarity = "Rare"
	case score >= scoreUncommon:
		t.Rarity = "Uncommon"
	default:
		t.Rarity = "Common"
	}
	return t, p
}

// ---------------------------------------------------------------------
// Public API - all pure reads. Nothing here writes state or costs a tx.
// ---------------------------------------------------------------------

// SeedFor builds the unsalted seed "<collectionID>:<tokenID>", the key
// the frontend already uses for a token. Kept for drop-in compatibility
// with gen0 call sites.
func SeedFor(collectionID, tokenID string) string {
	return collectionID + ":" + tokenID
}

// SeedForSalted builds a salted seed. The salt is a per-collection
// constant chosen at creation time; an empty salt degrades to SeedFor,
// so a collection that does not care about sniping behaves like gen0.
//
// The salt goes in FRONT of the token key because FNV-1a is sequential:
// a leading salt changes the hash state before the token bytes are even
// mixed in, so neighbouring token IDs do not stay neighbours.
func SeedForSalted(collectionID, tokenID, salt string) string {
	if salt == "" {
		return SeedFor(collectionID, tokenID)
	}
	return salt + "|" + collectionID + ":" + tokenID
}

// TraitsOf returns the decoded traits for a seed.
func TraitsOf(seed string) Traits {
	t, _ := derive(seed)
	return t
}

// RarityOf returns just the tier, for callers that only rank tokens.
func RarityOf(seed string) string {
	t, _ := derive(seed)
	return t.Rarity
}

// TraitString returns the traits in the compact "k=v;k=v" form that
// nft5x.MintWithTraits parses. Nine pairs, well under the 16-attribute
// and 64-character-per-value realm limits.
func TraitString(seed string) string {
	t, _ := derive(seed)
	return strings.Join([]string{
		"Palette=" + t.Palette,
		"Shape=" + t.Shape,
		"Ground=" + t.Ground,
		"Frame=" + t.Frame,
		"Finish=" + t.Finish,
		"Aura=" + t.Aura,
		"Elements=" + strconv.Itoa(t.Elements),
		"Symmetry=" + strconv.Itoa(t.Symmetry),
		"Rarity=" + t.Rarity,
	}, ";")
}

// finishStroke maps the Finish layer onto stroke width, and glowOpacity
// onto a shared opacity bump, so Finish is genuinely visible instead of
// being metadata-only.
func finishStroke(finish string) int {
	switch finish {
	case "Gloss":
		return 4
	case "Glow":
		return 5
	case "Foil":
		return 6
	default: // Matte
		return 3
	}
}

func auraRing(aura string) (int, int) { // width, opacity percent
	switch aura {
	case "Soft":
		return 4, 22
	case "Bright":
		return 8, 38
	case "Nova":
		return 14, 60
	default:
		return 0, 0
	}
}

// SVG renders the artwork for a seed as a standalone SVG document.
func SVG(seed string) string {
	t, p := derive(seed)
	r := newRNG(seed + "|art") // separate stream: trait draws never shift the art

	var b strings.Builder
	b.WriteString(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" width="512" height="512">`)
	b.WriteString(ufmt.Sprintf(`<rect width="512" height="512" fill="%s"/>`, p.bg))

	// --- ground layer ---
	switch t.Ground {
	case "Halo":
		b.WriteString(ufmt.Sprintf(
			`<circle cx="256" cy="256" r="200" fill="none" stroke="%s" stroke-width="1" opacity="0.35"/>`, p.c3))
	case "Grid":
		for i := 64; i < 512; i += 64 {
			b.WriteString(ufmt.Sprintf(
				`<line x1="%d" y1="0" x2="%d" y2="512" stroke="%s" stroke-width="1" opacity="0.18"/>`, i, i, p.c3))
			b.WriteString(ufmt.Sprintf(
				`<line x1="0" y1="%d" x2="512" y2="%d" stroke="%s" stroke-width="1" opacity="0.18"/>`, i, i, p.c3))
		}
	case "Rings":
		for rad := 60; rad <= 240; rad += 45 {
			b.WriteString(ufmt.Sprintf(
				`<circle cx="256" cy="256" r="%d" fill="none" stroke="%s" stroke-width="1" opacity="0.22"/>`, rad, p.c3))
		}
	case "Scatter":
		for i := 0; i < 40; i++ {
			b.WriteString(ufmt.Sprintf(
				`<circle cx="%d" cy="%d" r="2" fill="%s" opacity="0.30"/>`,
				16+r.intn(480), 16+r.intn(480), p.c3))
		}
	}

	// --- aura layer (four tiers instead of gen0's on/off ring) ---
	if w, op := auraRing(t.Aura); w > 0 {
		b.WriteString(ufmt.Sprintf(
			`<circle cx="256" cy="256" r="230" fill="none" stroke="%s" stroke-width="%d" opacity="0.%d"/>`,
			p.ink, w, op))
	}

	// --- composition: one pass, mirrored Symmetry times ---
	stroke := finishStroke(t.Finish)
	step := 360 / t.Symmetry
	for s := 0; s < t.Symmetry; s++ {
		b.WriteString(ufmt.Sprintf(`<g transform="rotate(%d 256 256)">`, s*step))
		for e := 0; e < t.Elements; e++ {
			color := p.c1
			switch r.intn(3) {
			case 1:
				color = p.c2
			case 2:
				color = p.ink
			}
			x := 96 + r.intn(320)
			y := 96 + r.intn(320)
			size := 12 + r.intn(70)
			opacity := 40 + r.intn(55) // percent, integer only
			if t.Finish == "Glow" || t.Finish == "Foil" {
				opacity = 55 + r.intn(40)
			}

			switch t.Shape {
			case "Orbit":
				b.WriteString(ufmt.Sprintf(
					`<circle cx="%d" cy="%d" r="%d" fill="none" stroke="%s" stroke-width="%d" opacity="0.%d"/>`,
					x, y, size, color, stroke, opacity))
			case "Lattice":
				b.WriteString(ufmt.Sprintf(
					`<rect x="%d" y="%d" width="%d" height="%d" fill="none" stroke="%s" stroke-width="%d" opacity="0.%d"/>`,
					x, y, size, size, color, stroke-1, opacity))
			case "Bloom":
				b.WriteString(ufmt.Sprintf(
					`<circle cx="%d" cy="%d" r="%d" fill="%s" opacity="0.%d"/>`,
					x, y, size/2, color, opacity))
			case "Shard":
				b.WriteString(ufmt.Sprintf(
					`<polygon points="%d,%d %d,%d %d,%d" fill="%s" opacity="0.%d"/>`,
					x, y, x+size, y+size/2, x+size/3, y+size, color, opacity))
			case "Weave":
				// two crossing strokes: reads as woven once mirrored
				b.WriteString(ufmt.Sprintf(
					`<line x1="%d" y1="%d" x2="%d" y2="%d" stroke="%s" stroke-width="%d" opacity="0.%d"/>`,
					x, y, x+size, y+size/3, color, stroke, opacity))
				b.WriteString(ufmt.Sprintf(
					`<line x1="%d" y1="%d" x2="%d" y2="%d" stroke="%s" stroke-width="%d" opacity="0.%d"/>`,
					x+size, y, x, y+size/3, color, stroke, opacity))
			case "Rift":
				// a jagged tear through the frame
				b.WriteString(ufmt.Sprintf(
					`<path d="M%d %d l %d %d l %d %d l %d %d" fill="none" stroke="%s" stroke-width="%d" opacity="0.%d"/>`,
					x, y, size/2, -size/3, size/3, size, size/2, -size/2,
					color, stroke, opacity))
			default: // Spiral
				b.WriteString(ufmt.Sprintf(
					`<path d="M%d %d q %d %d %d %d" fill="none" stroke="%s" stroke-width="%d" opacity="0.%d"/>`,
					x, y, size, -size, size*2, 0, color, stroke, opacity))
			}
		}
		b.WriteString(`</g>`)
	}

	// --- frame layer, drawn last so it always sits on top ---
	switch t.Frame {
	case "Thin":
		b.WriteString(ufmt.Sprintf(
			`<rect x="12" y="12" width="488" height="488" fill="none" stroke="%s" stroke-width="2" opacity="0.55"/>`, p.ink))
	case "Double":
		b.WriteString(ufmt.Sprintf(
			`<rect x="10" y="10" width="492" height="492" fill="none" stroke="%s" stroke-width="3" opacity="0.60"/>`, p.ink))
		b.WriteString(ufmt.Sprintf(
			`<rect x="24" y="24" width="464" height="464" fill="none" stroke="%s" stroke-width="1" opacity="0.45"/>`, p.c2))
	case "Ornate":
		b.WriteString(ufmt.Sprintf(
			`<rect x="8" y="8" width="496" height="496" fill="none" stroke="%s" stroke-width="4" opacity="0.70"/>`, p.ink))
		b.WriteString(ufmt.Sprintf(
			`<rect x="22" y="22" width="468" height="468" fill="none" stroke="%s" stroke-width="2" opacity="0.55"/>`, p.c2))
		for _, c := range [][2]int{{8, 8}, {504, 8}, {8, 504}, {504, 504}} {
			b.WriteString(ufmt.Sprintf(
				`<circle cx="%d" cy="%d" r="10" fill="none" stroke="%s" stroke-width="3" opacity="0.80"/>`,
				c[0], c[1], p.c1))
		}
	}

	b.WriteString(`</svg>`)
	return b.String()
}

// DataURI returns the artwork as a base64 data: URI, ready to be stored
// as a tokenURI. Base64 rather than raw utf8 because a tokenURI travels
// through JSON-RPC, shell arguments and HTML attributes on its way to a
// browser, and raw SVG contains quotes and angle brackets that at least
// one of those layers will mangle.
func DataURI(seed string) string {
	return "data:image/svg+xml;base64," + base64.StdEncoding.EncodeToString([]byte(SVG(seed)))
}

// Preview is a convenience for the frontend: traits and artwork for a
// token in a single qeval instead of two.
func Preview(collectionID, tokenID string) (string, string) {
	seed := SeedFor(collectionID, tokenID)
	return TraitString(seed), DataURI(seed)
}

// PreviewSalted is Preview for a collection that uses a seed salt.
func PreviewSalted(collectionID, tokenID, salt string) (string, string) {
	seed := SeedForSalted(collectionID, tokenID, salt)
	return TraitString(seed), DataURI(seed)
}

// Render makes the generator browsable from gnoweb: the index shows a
// sample drop, and :<seed> renders one piece with its traits.
func Render(path string) string {
	if path != "" {
		t := TraitsOf(path)
		return ufmt.Sprintf(
			"# gen1 \u00b7 %s\n\n![%s](%s)\n\n- Palette: %s\n- Shape: %s\n- Ground: %s\n"+
				"- Frame: %s\n- Finish: %s\n- Aura: %s\n- Elements: %d\n- Symmetry: %d\n"+
				"- Score: %d\n- Rarity: **%s**\n",
			path, path, DataURI(path), t.Palette, t.Shape, t.Ground,
			t.Frame, t.Finish, t.Aura, t.Elements, t.Symmetry, t.Score, t.Rarity)
	}

	out := "# gen1 \u2014 on-chain generative engine (second generation)\n\n" +
		"Pure functions: seed \u2192 traits \u2192 SVG \u2192 `data:` URI. No IPFS, no gateway.\n\n" +
		"1.254.400 trait combinations, score-based rarity over every layer, and an\n" +
		"optional per-collection seed salt so the rarity map is not public before\n" +
		"the first mint.\n\n## Sample drop (seeds `gen1:1` \u2026 `gen1:10`)\n\n"
	for i := 1; i <= 10; i++ {
		seed := "gen1:" + strconv.Itoa(i)
		t := TraitsOf(seed)
		out += ufmt.Sprintf("- [%s](:%s) \u2014 %s %s, %s frame, %s finish, %d elements, **%s**\n",
			seed, seed, t.Palette, t.Shape, t.Frame, t.Finish, t.Elements, t.Rarity)
	}
	return out
}

package nftgen1

import (
	"strings"
	"testing"
)

// Determinism is the entire value proposition: if the same seed ever
// rendered differently, every token minted from this engine would be
// unverifiable.
func TestDeterministic(t *testing.T) {
	for _, seed := range []string{"gen1:1", "3:7", "", "a very long seed string \u00e7\u00fc"} {
		if SVG(seed) != SVG(seed) {
			t.Fatalf("SVG(%q) not deterministic", seed)
		}
		if TraitString(seed) != TraitString(seed) {
			t.Fatalf("TraitString(%q) not deterministic", seed)
		}
	}
}

// The headline reason gen1 exists: at a full 1000-token drop gen0 put
// 112 tokens on a shared trait set. gen1 must stay in single digits.
func TestFullSupplyCollisions(t *testing.T) {
	seen := map[string]int{}
	for i := 1; i <= 1000; i++ {
		seen[TraitString(SeedFor("1", itoa(i)))]++
	}
	dupes := 0
	worst := 0
	for _, c := range seen {
		if c > 1 {
			dupes += c - 1
		}
		if c > worst {
			worst = c
		}
	}
	if dupes > 20 {
		t.Fatalf("too many shared trait sets: %d (gen0 had 112)", dupes)
	}
	if worst > 2 {
		t.Fatalf("a trait set repeats %dx", worst)
	}
}

// Artwork, not just metadata, has to diverge.
func TestArtDiverges(t *testing.T) {
	seen := map[string]bool{}
	for i := 1; i <= 60; i++ {
		s := SVG(SeedFor("gen1", itoa(i)))
		if seen[s] {
			t.Fatalf("duplicate artwork at token %d", i)
		}
		seen[s] = true
	}
}

// The salt is the anti-snipe mechanism: with a salt, knowing the token
// ID must tell you nothing about the traits, while determinism holds.
func TestSaltShiftsButStaysDeterministic(t *testing.T) {
	if SeedForSalted("1", "7", "") != SeedFor("1", "7") {
		t.Fatal("empty salt must degrade to the plain seed")
	}
	if SeedForSalted("1", "7", "abc") == SeedFor("1", "7") {
		t.Fatal("a salt must change the seed")
	}

	changed := 0
	for i := 1; i <= 100; i++ {
		plain := TraitString(SeedFor("1", itoa(i)))
		salted := TraitString(SeedForSalted("1", itoa(i), "9f3c1a"))
		if plain != salted {
			changed++
		}
		// same salt, same answer - twice
		if salted != TraitString(SeedForSalted("1", itoa(i), "9f3c1a")) {
			t.Fatalf("salted seed %d not deterministic", i)
		}
	}
	if changed < 90 {
		t.Fatalf("salt barely moved the map: only %d/100 changed", changed)
	}
}

func TestSVGWellFormed(t *testing.T) {
	for i := 1; i <= 40; i++ {
		s := SVG(SeedFor("3", itoa(i)))
		if !strings.HasPrefix(s, "<svg xmlns=") || !strings.HasSuffix(s, "</svg>") {
			t.Fatalf("token %d: bad envelope", i)
		}
		if strings.Count(s, "<g ") != strings.Count(s, "</g>") {
			t.Fatalf("token %d: unbalanced groups", i)
		}
		// A tokenURI this size is stored on chain forever at roughly
		// 0.1 GNOT/KB. gen1 draws up to 8x14 primitives, so the cap has
		// to be checked, not assumed.
		if len(s) > 32000 {
			t.Fatalf("token %d: svg too large (%d bytes)", i, len(s))
		}
	}
}

func TestDataURI(t *testing.T) {
	u := DataURI("gen1:1")
	if !strings.HasPrefix(u, "data:image/svg+xml;base64,") {
		t.Fatalf("unexpected prefix: %s", u[:40])
	}
	// nft5x classifies storage by the URI prefix; anything else here
	// would make an on-chain token report as an off-chain one.
	if strings.ContainsAny(u, " \n\"'<>") {
		t.Fatal("data URI must be transport-safe")
	}
	// The realm caps a URI at 700.000 chars.
	if len(u) > 700000 {
		t.Fatalf("data URI exceeds the realm URI limit: %d", len(u))
	}
}

// The trait string has to survive the "k=v;k=v" parser and the realm's
// 16-attribute / 64-char limits.
func TestTraitStringShape(t *testing.T) {
	parts := strings.Split(TraitString("gen1:4"), ";")
	if len(parts) != 9 {
		t.Fatalf("want 9 traits, got %d", len(parts))
	}
	for _, p := range parts {
		kv := strings.Split(p, "=")
		if len(kv) != 2 || kv[0] == "" || kv[1] == "" {
			t.Fatalf("malformed trait %q", p)
		}
		if len(kv[0]) > 64 || len(kv[1]) > 64 {
			t.Fatalf("trait %q exceeds the 64-char realm limit", p)
		}
	}
}

// Metadata and artwork are derived from one struct, so every visible
// layer must actually be drawn when the traits claim it.
func TestVisibleLayersMatchArt(t *testing.T) {
	for i := 1; i <= 120; i++ {
		seed := SeedFor("v", itoa(i))
		tr := TraitsOf(seed)
		art := SVG(seed)

		hasAura := strings.Contains(art, `r="230"`)
		if (tr.Aura != "None") != hasAura {
			t.Fatalf("seed %s: Aura=%s but ring=%t", seed, tr.Aura, hasAura)
		}

		hasFrame := strings.Contains(art, `height="488"`) ||
			strings.Contains(art, `height="492"`) ||
			strings.Contains(art, `height="496"`)
		if (tr.Frame != "None") != hasFrame {
			t.Fatalf("seed %s: Frame=%s but border=%t", seed, tr.Frame, hasFrame)
		}
	}
}

// Rarity must come from the whole trait set, not one flag. A Common
// token therefore has to be scoreless, and every tier must be reachable
// within a single 1000-token drop.
func TestRarityIsScoreBased(t *testing.T) {
	valid := map[string]bool{
		"Common": true, "Uncommon": true, "Rare": true,
		"Legendary": true, "Mythic": true,
	}
	counts := map[string]int{}
	for i := 1; i <= 1000; i++ {
		tr := TraitsOf(SeedFor("1", itoa(i)))
		if !valid[tr.Rarity] {
			t.Fatalf("unknown rarity %q", tr.Rarity)
		}
		if tr.Rarity == "Common" && tr.Score >= scoreUncommon {
			t.Fatalf("Common token with score %d", tr.Score)
		}
		if tr.Rarity == "Mythic" && tr.Score < scoreMythic {
			t.Fatalf("Mythic token with score %d", tr.Score)
		}
		if RarityOf(SeedFor("1", itoa(i))) != tr.Rarity {
			t.Fatal("RarityOf disagrees with TraitsOf")
		}
		counts[tr.Rarity]++
	}
	for tier := range valid {
		if counts[tier] == 0 {
			t.Fatalf("tier %s never appears in a 1000-token drop", tier)
		}
	}
	// The top tier has to stay scarce, or it is not a top tier.
	if counts["Mythic"] > 40 {
		t.Fatalf("Mythic too common: %d/1000", counts["Mythic"])
	}
	// ...and the bottom tier must not swallow the drop.
	if counts["Common"] > 450 {
		t.Fatalf("Common too dominant: %d/1000", counts["Common"])
	}
}

// Scarce traits must actually be scarce: the weights are the product
// design, so a table typo that flattens them should fail here.
func TestWeightsHold(t *testing.T) {
	pal := map[string]int{}
	shape := map[string]int{}
	for i := 1; i <= 1000; i++ {
		tr := TraitsOf(SeedFor("w", itoa(i)))
		pal[tr.Palette]++
		shape[tr.Shape]++
	}
	if pal["Prism"] == 0 || pal["Prism"] > 90 {
		t.Fatalf("Prism should be ~4%%, got %d/1000", pal["Prism"])
	}
	if shape["Rift"] == 0 || shape["Rift"] > 110 {
		t.Fatalf("Rift should be ~5%%, got %d/1000", shape["Rift"])
	}
	if pal["Emerald"] < 100 {
		t.Fatalf("Emerald should be ~18%%, got %d/1000", pal["Emerald"])
	}
}

func TestElementRanges(t *testing.T) {
	for i := 1; i <= 300; i++ {
		tr := TraitsOf(SeedFor("e", itoa(i)))
		if tr.Elements < 5 || tr.Elements > 14 {
			t.Fatalf("Elements out of range: %d", tr.Elements)
		}
		if tr.Symmetry < 2 || tr.Symmetry > 8 {
			t.Fatalf("Symmetry out of range: %d", tr.Symmetry)
		}
	}
}

func TestPreviewAndRender(t *testing.T) {
	traits, art := Preview("1", "5")
	if !strings.Contains(traits, "Rarity=") || !strings.HasPrefix(art, "data:image/svg+xml;base64,") {
		t.Fatal("Preview should return traits plus artwork")
	}
	sTraits, sArt := PreviewSalted("1", "5", "salt")
	if sTraits == traits && sArt == art {
		t.Fatal("PreviewSalted should follow the salted seed")
	}
	if idx := Render(""); !strings.Contains(idx, "gen1:10") {
		t.Fatal("index should list the sample drop")
	}
	if d := Render("gen1:2"); !strings.Contains(d, "data:image/svg+xml;base64,") {
		t.Fatal("detail page should embed the artwork")
	}
}

func itoa(i int) string {
	if i == 0 {
		return "0"
	}
	var b []byte
	for i > 0 {
		b = append([]byte{byte('0' + i%10)}, b...)
		i /= 10
	}
	return string(b)
}

package nft57

import "gno.land/p/nt/avl/v0"

// avlGet is the ONE place where this package touches avl.Tree.Get.
//
// The avl/v0 published on gno.land returns (value, exists); the one
// shipped with the pearl testnet's GNOROOT returns a single value. Every
// other line of this package is identical on both networks, so the whole
// difference is isolated here instead of being spread over every call
// site. Switch it with: python3 scripts/avl-shim.py <pearl|mainnet>
//
// AVL-VARIANT: pearl
func avlGet(t *avl.Tree, key string) any {
	return t.Get(key)
}

package nft57

import (
	"testing"

	"gno.land/p/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/tokens/grc721"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/uassert/v0"
)

// These tests pin the v5.4 mint-cost changes. Each one is written the same
// way: the cheaper implementation must give the SAME answer the v5.3
// implementation gave, because "cheaper" is only acceptable here if nothing
// a buyer or a market realm reads changes.

const (
	testCreator = address("g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3")
	testBuyer   = address("g1g67y6n35hx9llakmlpu2pd6tssn48as0gp6f50")
)

// newTestCollection builds a live collection in-realm so the mint paths can
// be exercised without a wallet transaction.
func newTestCollection(cur realm, id string, royaltyPct, maxPerWallet int64) *Collection {
	c := &Collection{
		id:           id,
		name:         "Cost " + id,
		symbol:       "COST",
		creator:      testCreator,
		maxSupply:    MaxCollectionSupply,
		publicMint:   true,
		royaltyPct:   royaltyPct,
		token:        grc721.NewNFTWithRoyalty(0, cur, "Cost "+id, "COST"),
		nextTokenID:  1,
		maxPerWallet: maxPerWallet,
		mintedBy:     avl.NewTree(),
	}
	collections.Set(id, c)
	return c
}

func dropTestCollection(id string) {
	collections.Remove(id)
}

// TestRoyaltyIsDerivedFromCollection covers v5.4 change 1. The per-token
// royalty row is gone, so the only remaining source of truth is the
// collection's own immutable terms - which is what the market realm quotes
// to a buyer.
func TestRoyaltyIsDerivedFromCollection(cur realm, t *testing.T) {
	newTestCollection(cur, "501", 7, 0)
	defer dropTestCollection("501")

	mint(cur, testBuyer, "501", "", "")

	// Paid to the CREATOR, not to the minter or the current holder.
	addr, owed, err := RoyaltyInfo("501", "1", 1000)
	uassert.NoError(t, err)
	uassert.Equal(t, testCreator.String(), addr.String())
	uassert.Equal(t, int64(70), owed)

	// Same percentage applies at any sale price, and it is a floor division
	// so the realm never over-pays a royalty it did not collect.
	_, owed2, _ := RoyaltyInfo("501", "1", 99)
	uassert.Equal(t, int64(6), owed2)

	// A token that does not exist must ERROR rather than quietly report
	// "no royalty owed" - otherwise a sale of a burned token could skip the
	// creator's cut.
	_, _, err = RoyaltyInfo("501", "2", 1000)
	uassert.Error(t, err)
}

// TestZeroRoyaltyCollectionOwesNothing keeps the EIP-2981 "no royalty"
// signal intact: empty address and 0, not the creator with 0.
func TestZeroRoyaltyCollectionOwesNothing(cur realm, t *testing.T) {
	newTestCollection(cur, "502", 0, 0)
	defer dropTestCollection("502")

	mint(cur, testBuyer, "502", "", "")

	addr, owed, err := RoyaltyInfo("502", "1", 1000)
	uassert.NoError(t, err)
	uassert.Equal(t, "", addr.String())
	uassert.Equal(t, int64(0), owed)
}

// TestTokensOfCollectionIsDerived covers v5.4 change 2: no index tree, same
// list. Burned tokens must disappear and their IDs must never come back.
func TestTokensOfCollectionIsDerived(cur realm, t *testing.T) {
	c := newTestCollection(cur, "503", 0, 0)
	defer dropTestCollection("503")

	for i := 0; i < 3; i++ {
		mint(cur, testBuyer, "503", "", "")
	}

	all := TokensOfCollection("503", 0, 0)
	uassert.Equal(t, 3, len(all))
	uassert.Equal(t, "1", all[0])
	uassert.Equal(t, "3", all[2])

	// Burn the middle token directly on the ledger (Burn() itself needs a
	// wallet caller); the derived view must skip the hole.
	uassert.NoError(t, c.token.Burn(grc721.TokenID("2")))

	live := TokensOfCollection("503", 0, 0)
	uassert.Equal(t, 2, len(live))
	uassert.Equal(t, "1", live[0])
	uassert.Equal(t, "3", live[1])

	// A burn must not re-open the ID: the next mint is 4, not 2.
	uassert.Equal(t, "4", mint(cur, testBuyer, "503", "", ""))
}

// TestTokensOfCollectionSortsNumerically is the reason v5.3 needed padded
// keys at all: "10" has to come after "9", not after "1".
func TestTokensOfCollectionSortsNumerically(cur realm, t *testing.T) {
	newTestCollection(cur, "504", 0, 0)
	defer dropTestCollection("504")

	for i := 0; i < 11; i++ {
		mint(cur, testBuyer, "504", "", "")
	}

	ids := TokensOfCollection("504", 0, 0)
	uassert.Equal(t, 11, len(ids))
	uassert.Equal(t, "9", ids[8])
	uassert.Equal(t, "10", ids[9])
	uassert.Equal(t, "11", ids[10])

	// Pagination stays stable across the two-digit boundary.
	page := TokensOfCollection("504", 8, 2)
	uassert.Equal(t, 2, len(page))
	uassert.Equal(t, "9", page[0])
	uassert.Equal(t, "10", page[1])
}

// TestWalletCounterOnlyKeptWhenCapped covers v5.4 change 3: the counter is
// skipped when there is no cap, but the cap itself must still be enforced
// exactly as before when one is set.
func TestWalletCounterOnlyKeptWhenCapped(cur realm, t *testing.T) {
	uncapped := newTestCollection(cur, "505", 0, 0)
	defer dropTestCollection("505")

	mint(cur, testBuyer, "505", "", "")
	mint(cur, testBuyer, "505", "", "")
	// No cap -> no counter written -> the view reports 0 and nothing is
	// enforced against it.
	uassert.Equal(t, int64(0), MintedByWallet("505", testBuyer))
	uassert.Equal(t, int64(0), int64(uncapped.mintedBy.Size()))

	capped := newTestCollection(cur, "506", 0, 2)
	defer dropTestCollection("506")

	mint(cur, testBuyer, "506", "", "")
	uassert.Equal(t, int64(1), MintedByWallet("506", testBuyer))
	mint(cur, testBuyer, "506", "", "")
	uassert.Equal(t, int64(2), MintedByWallet("506", testBuyer))
	uassert.Equal(t, int64(1), int64(capped.mintedBy.Size()))

	// Third mint by the same wallet is refused - the cap survived the
	// optimisation.
	uassert.PanicsWithMessage(t, cur,
		"wallet has reached this collection's per-wallet mint limit of 2",
		func() { mint(cur, testBuyer, "506", "", "") })

	// A different wallet is unaffected by another wallet's usage.
	mint(cur, testCreator, "506", "", "")
	uassert.Equal(t, int64(1), MintedByWallet("506", testCreator))
}

// Package nft57 is the v5.7 GRC-721 NFT factory realm for gnoNFT.
//
// WHAT CHANGED VS V5.5 (creator onboarding + mint cost; no new powers)
//
// v5.5 was complete for OUR use case (a fully on-chain generative
// collection) but unusable for the creators a marketplace has to attract:
// someone arriving from Ethereum has N images plus N metadata JSON files on
// IPFS and a single folder CID. Ethereum spends ONE write on that CID and
// computes tokenURI(id) = baseURI + id; v5.5 had no such derivation, so the
// only route was QueuePresetURI called N times - N transactions to open one
// collection. That is not a frontend limitation, it is a missing line in an
// immutable realm, which is exactly the kind of thing that must be fixed
// BEFORE mainnet.
//
//  1. tokenURI falls back to baseURI + tokenID. Resolution order is now:
//     generative seed (derived) -> per-token stored URI -> baseURI+tokenID.
//     A 1000-piece IPFS collection therefore costs one baseURI write
//     instead of 1000 preset writes, and each token stores no URI at all.
//
//  2. Reveal exists but cannot be abused: SetBaseURI is creator-only and
//     usable AT MOST ONCE, after which baseURILocked is permanently true
//     and no code path can clear it. Pre-sale placeholder art is therefore
//     supported, while "the creator edits the metadata after you bought
//     it" - a real, repeatedly exploited failure on Ethereum - is
//     structurally impossible rather than merely discouraged. A creator who
//     never needs a reveal can call LockBaseURI to prove that up front.
//
//  3. Generative seeds are no longer STORED. v5.5 already derived traits
//     from the seed, but still wrote the seed itself - and the seed is
//     nftgen1.SeedFor(collectionID, tokenID), i.e. literally
//     collectionID + ":" + tokenID. It was a per-token copy of the two
//     strings the caller must already supply in order to ask about the
//     token, so it is derived on read now (same trick as v5.4 change 2).
//     Verified on pearl-1: TokenSeed("1","2") == "1:2".
//
//  4. collectionURI carries collection-level metadata (banner, logo,
//     links) - the OpenSea contractURI equivalent - so an incoming creator
//     can present a collection page without us hosting anything.
//
//  5. MintBatch mints up to MaxMintBatch tokens in ONE transaction, for
//     creators who pre-mint inventory before selling. It is a loop over
//     the same mint path, so every check (supply, per-wallet cap, public
//     mint, generative mode) applies per token exactly as before.
//
// WHAT CHANGED VS V5.4 (security + scope; no new powers, no admin)
//
//  1. Artwork URIs are validated ON CHAIN (assertSafeURI), on
//     CreateCollection(baseURI), Mint(tokenURI) and QueuePresetURI(uri).
//     Only https://, ipfs://, ar:// and data:image/ | data:application/json
//     are accepted. v5.4 persisted whatever scheme the caller supplied, so
//     a javascript: or data:text/html payload could be burned into the
//     chain permanently and then executed by any client - wallet, explorer
//     or third-party frontend - that rendered it. The realm cannot rely on
//     "the frontend will sanitize it"; an immutable record is forever.
//
//  2. No migration gate. v5.4 shipped migrate54.gno so v5.2/v5.3 holders
//     could reclaim tokens. gnoNFT launches on mainnet from a CLEAN LEDGER
//     (testnet tokens are not carried over), so v5.5 ships without the
//     gate: smaller package, cheaper deploy, and exactly the shape that
//     goes to mainnet. This does not weaken the migration policy below - a
//     future successor is still born with its gate compiled in at deploy
//     time, taking THIS realm as its source.
//
// WHAT CHANGED VS V5.3 (mint cost only — no new features, no new powers)
//
// v5.3 measured 7,782 B of storage per creator mint and 14,709 B per public
// mint on pearl-1. Every byte below was being written for data the realm
// could already derive, so v5.4 stops writing it. Nothing here relaxes a
// check, and no view changes its answer.
//
//  1. No per-token royalty row. v5.3 wrote (creator, royaltyPct) into the
//     grc721 royalty tree for EVERY token, but royaltyPct is fixed at
//     CreateCollection and creator can never be reassigned, so all N rows
//     of a collection were byte-identical copies of two collection fields.
//     RoyaltyInfo now computes the answer from the collection record. The
//     market's guarantee is unchanged: the royalty is set by the
//     collection's immutable terms, and the token holder cannot alter it.
//
//  2. No collectionTokens index. Token IDs are consecutive by construction
//     (nextTokenID only increases; a burn never re-opens a slot), so the
//     live set is 1..nextTokenID-1 minus what grc721 no longer owns.
//     TokensOfCollection derives that at read time instead of maintaining a
//     padded-key index on every mint and burn. It is a read-only view, so
//     the scan is paid by the RPC query rather than by a transaction, and
//     no write path calls it.
//
//  3. The per-wallet counter is only kept when a cap exists. With
//     maxPerWallet == 0 there is nothing to check, yet v5.3 still created
//     an AVL node per minting wallet — which is exactly why a public mint
//     by a fresh wallet cost about twice a creator mint: new tree nodes
//     instead of in-place updates.
//
// WHAT CHANGED VS V5 (all three are security or cost fixes, no new features)
//
//  A. Generative traits are DERIVED, not stored. v5 wrote the seed AND the
//     seven traits nftgen1 derives from that same seed, so every generative
//     mint paid ~12-20 KB of storage deposit (1.5-2.3 GNOT measured on
//     pearl-1) to persist data that is a pure function of a string the realm
//     already keeps. Here MintGenerative stores only the seed and
//     TokenAttributes rebuilds the traits at read time. Reads are free
//     qevals and nftgen1 is a fixed-cost pure function, so this is a strict
//     cost win with no new gas surface.
//
//  B. Trait spoofing is closed. v5.mint() stored whatever trait string the
//     CALLER supplied and only gated on publicMint, so in any public-mint
//     collection a stranger could mint themselves a token carrying
//     "Rarity=Legendary" and poison the marketplace rarity filter. In v5.2
//     only the collection creator may supply traits by hand; everyone else
//     mints traitless tokens or, in a generative collection, tokens whose
//     traits are the deterministic output of the engine. Rarity therefore
//     cannot be forged by anyone, creator included, in a generative
//     collection.
//
//  C. The rendering engine is PINNED per collection. Derived traits mean a
//     token's appearance now depends on live code rather than a stored blob,
//     so a collection records which engine realm it was created against
//     (Engine in CollectionInfo) at the moment it is marked generative.
//     gno.land realms are immutable, so a pinned engine can never change
//     under an existing token; a future nftgen1 is a different pkgpath and
//     therefore a different, explicitly recorded engine.
//
// Additionally a generative collection now refuses Mint / MintWithTraits /
// MintNext outright: mixing hand-written art or hand-written traits into a
// collection that advertises "every token is derived from its seed" would
// make that promise unverifiable.
//
// MIGRATION POLICY (why old tokens are safe when v6 arrives)
//
// Realms are immutable, so a fix always means a new pkgpath, and the
// project treats that as a first-class event rather than an accident:
// every piece of state a successor realm needs in order to reproduce a
// token exactly - seed, traits, URI, creator, royalty, per-collection
// config - is exposed here as a pure public read (GetCollection,
// TokenSeed, TokenAttributes, TokenURI, TokenMetadata, OwnerOf,
// RoyaltyInfo, TokensOfCollection). A successor can therefore import this
// realm, verify ownership on chain, and re-mint a byte-identical token to
// the rightful owner without any admin key, snapshot file or trusted
// operator existing anywhere in the path. Nothing in this realm can be
// switched off, redirected or upgraded by its deployer - there is
// deliberately no owner, no pause switch and no proxy.
//
// Inherited from v2 (kept verbatim below because the reasoning still
// applies):
//
// WHY A V2 AT ALL
//
// gno.land packages are immutable once deployed, so none of the fixes
// below could be retrofitted onto gno.land/r/g1hx4z2.../nft. v2 was
// deployed while v1 still held 0 minted tokens, i.e. at the only moment
// in the project's life where migrating costs nothing.
//
// WHAT CHANGED VS V1
//
//  1. Authorization no longer uses unsafe.OriginCaller().
//     v1 justified OriginCaller with a comment claiming PreviousRealm-based
//     auth "was not a reliable immediate-caller check". That misread the
//     upstream warning: the unreliable symbol is unsafe.PreviousRealm(),
//     which stack-walks. A threaded `cur realm` parameter's cur.Previous()
//     is, in gno.land's own words, "statically scoped to a crossing
//     function and cannot lie". OriginCaller is gno's tx.origin and the
//     stdlib documents it as the Solidity tx.origin phishing class: any
//     realm the user calls could invoke
//     nft.SetApprovalForAll(cross(cur), id, attacker, true) and have v1
//     attribute it to the *user*, handing an attacker every NFT that user
//     owns. Every state-changing function here derives its caller from
//     cur.Previous().Address() instead, so a malicious intermediate realm
//     can only ever act as itself.
//
//  2. Max supply is enforced against the ID counter, not the live count.
//     v1 checked `token.TokenCount() >= maxSupply`, and TokenCount() is a
//     live count that Burn decrements — so burning re-opened mint slots
//     and a 10-supply collection could mint unbounded tokens over time.
//     v2 gates on nextTokenID and tracks mintedTotal separately, so
//     "10 max supply" means 10 tokens ever, forever.
//
//  3. Per-wallet mint caps are trustless. v1's cap lived in a separate
//     nftlimits realm that nft.Mint never consulted, so it was bypassable
//     by calling Mint directly with gnokey. Here the cap is checked inside
//     Mint itself.
//
//  4. Preset artwork queues are built in, for the same reason.
//
//  5. On-chain attributes. Traits can be stored on-chain at mint time and
//     TokenMetadata() assembles a full metadata JSON document inside the
//     realm, so a token can be fully self-describing with no IPFS, no
//     gateway and no pinning service in the trust path.
//
//  6. New views the frontend previously had to brute-force:
//     TokensOfCollection (v1 had no way to list a collection's tokens
//     except probing IDs one by one) and MintedByWallet.
package nft57

import (
	"chain"
	"chain/runtime"
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"

	"gno.land/p/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/tokens/grc721"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"

	"gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nftgen1"
)

const (
	// MaxRoyaltyPercent caps creator royalties at 50% of a secondary sale.
	MaxRoyaltyPercent = 50
	// MaxCollectionSupply is the platform-wide ceiling on a single
	// collection. It exists so pagination, indexing and gas stay
	// predictable, and so a "collection" stays a collection instead of an
	// unbounded minting faucet. Raising it later means a new realm.
	MaxCollectionSupply = 1000
	// MaxAttributesPerToken and MaxTraitLen bound on-chain trait storage so
	// the attributes tree can't be used as unmetered blob storage.
	MaxAttributesPerToken = 16
	MaxTraitLen           = 64
	// MaxNameLen / MaxDescriptionLen / MaxURILen bound collection metadata.
	MaxNameLen        = 64
	MaxSymbolLen      = 16
	MaxDescriptionLen = 512
	MaxURILen         = 700_000 // fully on-chain data: URIs are the point; MaxTxBytes is the real ceiling
	// MaxMintBatch bounds one MintBatch call so a creator pre-minting
	// inventory cannot build a transaction that exceeds the block gas limit.
	MaxMintBatch = 25
	// SaltRevealGraceBlocks lets a collection that never sells out reveal
	// its salt anyway, so a stalled mint cannot trap the artwork behind
	// pre-reveal placeholders forever.
	SaltRevealGraceBlocks = 1_000_000
	// MaxSecretLen bounds the revealed pre-image kept on chain for
	// verification.
	MaxSecretLen = 128
)

// Engine is the generative engine this realm renders seeds with. It is
// recorded on a collection when the collection is marked generative, so a
// token always names the exact immutable pkgpath that produced it.
const Engine = "gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nftgen1"

// nftToken is the subset of *grc721.royaltyNFT this realm depends on.
// grc721.NewNFTWithRoyalty returns a pointer to an unexported concrete
// type, so it can't be named as a struct field type directly; Gno
// interface satisfaction is structural, so this local interface lets us
// store it in Collection.token.
type nftToken interface {
	Name() string
	Symbol() string
	TokenCount() int64
	BalanceOf(addr address) (int64, error)
	OwnerOf(tid grc721.TokenID) (address, error)
	TokenURI(tid grc721.TokenID) (string, error)
	SetTokenURI(caller address, tid grc721.TokenID, tURI grc721.TokenURI) (bool, error)
	IsApprovedForAll(owner, operator address) bool
	Approve(caller, to address, tid grc721.TokenID) error
	GetApproved(tid grc721.TokenID) (address, error)
	SetApprovalForAll(caller, operator address, approved bool) error
	TransferFrom(caller, from, to address, tid grc721.TokenID) error
	Mint(to address, tid grc721.TokenID) error
	Burn(tid grc721.TokenID) error
	// v5.4 no longer writes a per-token royalty record (see package doc,
	// v5.4 change 1), so the royalty half of the grc721 surface is not part of
	// what this realm needs from its token backend any more.
}

// Attribute is one on-chain trait of a token (OpenSea-style trait_type/value).
type Attribute struct {
	TraitType string
	Value     string
}

// Collection is one user-created NFT collection living inside this realm.
type Collection struct {
	id          string
	name        string
	symbol      string
	description string
	baseURI     string
	// collectionURI points at collection-level metadata (banner, logo,
	// links): the OpenSea contractURI equivalent. Creator-editable, because
	// unlike artwork it describes the storefront rather than the asset
	// somebody bought.
	collectionURI string
	// baseURILocked is a one-way latch. SetBaseURI sets it and nothing in
	// this realm can ever clear it, so "the art can still change" is a
	// question the chain answers instead of the creator.
	baseURILocked bool
	creator       address
	maxSupply     int64
	publicMint    bool // if true, anyone can Mint; otherwise only the creator
	royaltyPct    int64
	token         nftToken

	// nextTokenID only ever increases. It is the supply gate (see the
	// package doc, change #2): burning a token does NOT free its slot.
	nextTokenID int64
	// mintedTotal counts tokens ever minted; token.TokenCount() counts
	// tokens currently alive. They differ once anything is burned, and the
	// UI wants to show both.
	mintedTotal int64

	// maxPerWallet is a trustless per-wallet cap (0 = unlimited), checked
	// inside Mint. mintedBy tracks lifetime mints per wallet, so the cap
	// can't be reset by burning or transferring away.
	maxPerWallet int64
	mintedBy     *avl.Tree // address.String() -> int64

	// presetURIs is an optional creator-supplied reveal queue; when it is
	// non-empty, MintNext draws the next un-revealed URI instead of
	// trusting whatever URI the minter passes.
	presetURIs []string
	presetNext int

	// onchainTokens / ipfsTokens record where each minted token's artwork
	// actually lives, so the UI can show an honest "fully on-chain" badge
	// instead of trusting the creator's word. Counted at mint time over
	// lifetime mints: burning does not decrement, same as mintedTotal.
	onchainTokens int64
	ipfsTokens    int64

	// generative marks a collection whose artwork is produced by the
	// on-chain nftgen1 engine. Such tokens store only a short seed; the
	// data: URI is rebuilt at read time by TokenURI, which is what makes a
	// generative mint cost gas instead of ~2 GNOT of storage deposit.
	generative bool

	// --- v5.7 seed salt (commit-reveal) ---
	//
	// saltCommit is sha256(secret) in hex, published before the first
	// mint: it binds the creator to one secret while telling the public
	// nothing, because sha256 cannot be inverted.
	//
	// saltEntropy accumulates what the creator could NOT know when they
	// committed: every generative mint folds in the minter's address and
	// the height it landed at.
	//
	// seedSalt is the final salt, written exactly once by RevealSeedSalt
	// from both halves. saltRevealed is a one-way latch, like
	// baseURILocked: no code here can ever clear it. saltSecret keeps the
	// revealed pre-image on chain so anybody can re-verify the commitment
	// for as long as the collection exists.
	saltCommit       string
	saltEntropy      int64
	seedSalt         string
	saltSecret       string
	saltRevealed     bool
	saltRevealedAt   int64
	saltRevealMinted int64

	// engine pins the pkgpath of the generator this collection's tokens are
	// rendered by. Set once, when the collection is marked generative, and
	// never rewritten - see package doc, change C.
	engine string

	createdAt int64
}

// CollectionInfo is the read-only, exported view of a Collection.
// Minted is the live (un-burned) count, kept under v1's field name so the
// frontend's existing decoder keeps working; MintedTotal is new.
type CollectionInfo struct {
	ID               string
	Name             string
	Symbol           string
	Description      string
	BaseURI          string
	Creator          address
	MaxSupply        int64
	Minted           int64
	MintedTotal      int64
	PublicMint       bool
	RoyaltyPct       int64
	MaxPerWallet     int64
	PresetsTotal     int64
	PresetsRemaining int64
	CreatedAt        int64
	// New in v4. Appended at the end so existing positional decoders keep
	// working for every field before them.
	OnchainTokens int64
	IpfsTokens    int64
	StorageKind   string
	// New in v5: true when tokens are rendered from an on-chain seed.
	Generative bool
	// New in v5.2: the pinned generative engine pkgpath ("" when the
	// collection is not generative).
	Engine string
	// New in v5.7: collection-level metadata URI, and whether the baseURI
	// can still be changed once (false) or is frozen forever (true).
	CollectionURI string
	BaseURILocked bool

	// New in v5.7: the seed-salt commitment and, after the reveal, every
	// input needed to re-derive and verify the salt without trusting the
	// creator. SaltCommit == "" means this collection never committed a
	// salt and therefore behaves like v5.6 (traits public from block one).
	// SaltPending == true means the artwork is still a placeholder.
	SaltCommit       string
	SaltPending      bool
	SaltRevealed     bool
	SeedSalt         string
	SaltSecret       string
	SaltEntropy      int64
	SaltRevealedAt   int64
	SaltRevealMinted int64
}

var (
	collections          = avl.NewTree() // id -> *Collection
	collectionsByCreator = avl.NewTree() // "creator:id" -> id
	ownerIndex           = avl.NewTree() // "owner:collectionId:tokenId" -> true
	attributes           = avl.NewTree() // "collectionId:tokenId" -> []Attribute
	collCount            int64
)

// callerOf returns the identity this realm authorizes against: the
// immediate caller frame. For a direct wallet call that is the signer;
// for a cross-realm call it is the calling realm's own address, never the
// original signer. See the package doc, change #1.
func callerOf(cur realm) address {
	return cur.Previous().Address()
}

// CreateCollection registers a brand-new GRC-721 collection owned by the
// caller and returns its collection ID. Set publicMint to true to let
// anyone mint into the collection; otherwise only the creator can. Pass
// maxPerWallet = 0 for no per-wallet cap.
func CreateCollection(cur realm, name, symbol, description, baseURI string, maxSupply, royaltyPct, maxPerWallet int64, publicMint bool) string {
	caller := callerOf(cur)

	if name == "" {
		panic("name must not be empty")
	}
	if len(name) > MaxNameLen {
		panic("name too long (max " + strconv.Itoa(MaxNameLen) + " chars)")
	}
	if len(symbol) > MaxSymbolLen {
		panic("symbol too long (max " + strconv.Itoa(MaxSymbolLen) + " chars)")
	}
	if len(description) > MaxDescriptionLen {
		panic("description too long (max " + strconv.Itoa(MaxDescriptionLen) + " chars)")
	}
	if len(baseURI) > MaxURILen {
		panic("baseURI too long")
	}
	assertSafeURI(baseURI, "baseURI")
	if maxSupply <= 0 {
		panic("maxSupply must be positive")
	}
	if maxSupply > MaxCollectionSupply {
		panic("maxSupply must be at most " + strconv.Itoa(MaxCollectionSupply))
	}
	if royaltyPct < 0 || royaltyPct > MaxRoyaltyPercent {
		panic("royaltyPct must be between 0 and " + strconv.Itoa(MaxRoyaltyPercent))
	}
	if maxPerWallet < 0 {
		panic("maxPerWallet must be >= 0 (0 means unlimited)")
	}

	collCount++
	id := strconv.FormatInt(collCount, 10)

	c := &Collection{
		id:           id,
		name:         name,
		symbol:       symbol,
		description:  description,
		baseURI:      baseURI,
		creator:      caller,
		maxSupply:    maxSupply,
		publicMint:   publicMint,
		royaltyPct:   royaltyPct,
		token:        grc721.NewNFTWithRoyalty(0, cur, name, symbol),
		nextTokenID:  1,
		maxPerWallet: maxPerWallet,
		mintedBy:     avl.NewTree(),
		createdAt:    runtime.ChainHeight(),
	}
	collections.Set(id, c)
	collectionsByCreator.Set(caller.String()+":"+id, id)

	chain.Emit(
		"CollectionCreated",
		"id", id,
		"creator", caller.String(),
		"name", name,
		"symbol", symbol,
	)

	return id
}

// Mint mints the next token in a collection to the caller and returns the
// new token ID.
func Mint(cur realm, collectionID, tokenURI string) string {
	assertNotGenerative(collectionID)
	return mint(cur, callerOf(cur), collectionID, tokenURI, "")
}

// MintWithTraits mints like Mint and additionally records on-chain traits.
// traits is a compact "trait=value;trait=value" string because gno.land's
// vm.MsgCall only carries scalar string arguments — the same reason batch
// minting loops single calls instead of passing an array.
// Only the collection's creator may hand-write traits: a stranger minting
// into a public collection must not be able to award themselves
// "Rarity=Legendary" and poison the marketplace filter (package doc,
// change B). Public minters can still mint - they just cannot dictate
// metadata that the market prices.
func MintWithTraits(cur realm, collectionID, tokenURI, traits string) string {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if c.generative {
		panic("this collection is generative; its traits come from the engine - use MintGenerative")
	}
	if traits != "" && caller != c.creator {
		panic("only the collection's creator can set traits by hand; use Mint instead")
	}
	return mint(cur, caller, collectionID, tokenURI, traits)
}

// MintNext draws the next un-revealed URI from the collection's preset
// queue and mints it to the caller, so the minter has no say over which
// artwork they receive.
func MintNext(cur realm, collectionID string) string {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if c.generative {
		panic("this collection is generative; use MintGenerative")
	}
	if len(c.presetURIs) == 0 {
		panic("this collection has no preset artwork queue - mint normally instead")
	}
	if c.presetNext >= len(c.presetURIs) {
		panic("no preset artwork left to reveal - the queue is exhausted")
	}
	uri := c.presetURIs[c.presetNext]
	c.presetNext++
	return mint(cur, caller, collectionID, uri, "")
}

func mint(cur realm, caller address, collectionID, tokenURI, traits string) string {
	c := mustGetCollection(collectionID)

	if !c.publicMint && caller != c.creator {
		panic("minting into this collection is restricted to its creator")
	}
	// Supply gate on the ID counter, not the live count: burning must not
	// re-open a slot (see package doc, change #2).
	if c.nextTokenID > c.maxSupply {
		panic("collection has reached its max supply")
	}
	if len(tokenURI) > MaxURILen {
		panic("tokenURI too long")
	}
	assertSafeURI(tokenURI, "tokenURI")

	// Trustless per-wallet cap, counted over lifetime mints so it survives
	// burning and transferring away (see package doc, change #3).
	if c.maxPerWallet > 0 {
		if mintedByWallet(c, caller) >= c.maxPerWallet {
			panic("wallet has reached this collection's per-wallet mint limit of " +
				strconv.FormatInt(c.maxPerWallet, 10))
		}
	}

	attrs := parseTraits(traits)

	tidStr := strconv.FormatInt(c.nextTokenID, 10)
	c.nextTokenID++
	c.mintedTotal++
	tid := grc721.TokenID(tidStr)

	if err := c.token.Mint(caller, tid); err != nil {
		panic(err)
	}
	if tokenURI != "" {
		if _, err := c.token.SetTokenURI(caller, tid, grc721.TokenURI(tokenURI)); err != nil {
			panic(err)
		}
	}
	// Where does this token's artwork live? A token with no URI of its own
	// inherits the collection's baseURI, so classify whichever one applies.
	effURI := tokenURI
	if effURI == "" {
		effURI = c.baseURI
	}
	if strings.HasPrefix(effURI, "data:") {
		c.onchainTokens++
	} else if strings.HasPrefix(effURI, "ipfs://") {
		c.ipfsTokens++
	}

	// Only pay for the per-wallet counter when a cap actually exists to
	// check it against (see package doc, v5.4 change 3). An uncapped
	// collection's first mint by a new wallet used to create a whole AVL
	// node nothing ever read.
	if c.maxPerWallet > 0 {
		c.mintedBy.Set(caller.String(), mintedByWallet(c, caller)+1)
	}
	ownerIndex.Set(caller.String()+":"+collectionID+":"+tidStr, true)
	if len(attrs) > 0 {
		attributes.Set(collectionID+":"+tidStr, attrs)
	}

	chain.Emit(
		"NFTMinted",
		"collection", collectionID,
		"tokenId", tidStr,
		"to", caller.String(),
	)

	return tidStr
}

// SetGenerative marks (or unmarks) a collection as generative, meaning
// its tokens are minted with MintGenerative and rendered from a seed by
// the on-chain nftgen1 engine. Creator-only, and refused once anything
// has been minted so a collection can never change what its existing
// tokens look like.
func SetGenerative(cur realm, collectionID string, generative bool) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if caller != c.creator {
		panic("only the collection's creator can change its generative mode")
	}
	if c.mintedTotal > 0 {
		panic("collection already has minted tokens; generative mode is fixed")
	}
	c.generative = generative
	if generative {
		c.engine = Engine
	} else {
		c.engine = ""
		// Nothing was minted (checked above), so no token's art depends on
		// the commitment yet; drop it so a later generative run starts from
		// a clean commit instead of inheriting a stale one.
		c.saltCommit = ""
		c.saltEntropy = 0
	}
}

// MintGenerative mints the next token of a generative collection to the
// caller. No artwork is stored: the token keeps a seed, and its traits
// are the ones nftgen1 derives from that same seed, so the trait filter
// in the marketplace keeps working exactly as it does for stored art.
func MintGenerative(cur realm, collectionID string) string {
	return mintGenerativeOne(cur, callerOf(cur), collectionID)
}

// mintGenerativeOne is the single-token generative mint path, shared by
// MintGenerative and MintBatch so a batched mint can never diverge from a
// single one. caller is resolved once by the exported entry point: taking
// it as a parameter rather than re-deriving it per token keeps the batch
// loop from depending on the call frame it happens to run in.
func mintGenerativeOne(cur realm, caller address, collectionID string) string {
	c := mustGetCollection(collectionID)
	if !c.generative {
		panic("this collection is not generative; use Mint or MintNext instead")
	}

	// Neither the traits NOR the seed are written: both are pure functions
	// of (collectionID, tokenID), which the caller must already know to ask
	// about the token at all. v5 stored traits and seed and paid 12-20 KB of
	// deposit per token (package doc, change A); v5.5 still stored the seed;
	// v5.7 stores neither (package doc, v5.7 change 3).
	tidStr := mint(cur, caller, collectionID, "", "")

	// Fold this mint into the collection's entropy while the salt is
	// still pending. These inputs are public, but they did not exist when
	// the creator committed, which is exactly the property that stops a
	// creator from choosing the trait map their own wallet will receive.
	if revealPending(c) {
		c.saltEntropy = mixEntropy(c.saltEntropy, caller, runtime.ChainHeight(), tidStr)
	}

	// Empty while the salt is pending: seedOf refuses to hand out a real
	// seed before the salt is public, so no mint receipt can leak the map.
	seed := seedOf(c, tidStr)

	// The artwork is produced and served entirely by on-chain code, so it
	// is on-chain in the strongest sense - there is not even a stored blob
	// that could rot. mint() classifies by URI and a generative mint has
	// none, so it only counted this token if the collection's baseURI is
	// itself a data: URI; guard against counting it twice.
	if !strings.HasPrefix(c.baseURI, "data:") {
		c.onchainTokens++
	}

	chain.Emit(
		"GenerativeMinted",
		"collection", collectionID,
		"tokenId", tidStr,
		"seed", seed,
		"revealed", strconv.FormatBool(!revealPending(c)),
		"to", caller.String(),
	)

	return tidStr
}

// --- v5.7 seed salt: commit, reveal, verify ---------------------------------
//
// A generative token's traits are a pure function of its seed, and in v5.6
// that seed was just (collectionID, tokenID). Honest, but public before the
// sale: anyone could enumerate all 1000 seeds, rank them and buy only the
// good ones (scripts/gen-snipe.py does exactly that against v5.6).
//
// v5.7 puts a per-collection salt in front of the seed and decides that salt
// with commit-reveal. It has to be commit-reveal rather than something the
// realm derives by itself: this chain exposes no block hash and no
// randomness to a realm - only ChainHeight - so any salt computed here from
// chain data could be recomputed by anybody reading this source, which is
// no protection at all.
//
//  1. CommitSeedSalt publishes sha256(secret) before the first mint. The
//     creator is bound to one secret from then on, and the public learns
//     nothing because sha256 cannot be inverted.
//  2. every generative mint folds the minter's address and block height
//     into saltEntropy - values the creator could not know at commit time.
//  3. RevealSeedSalt, allowed once supply is exhausted (or after
//     SaltRevealGraceBlocks if the mint stalls), checks the secret against
//     the commitment and writes the final salt, once, forever.
//
// So the creator cannot pick the map (they do not control the entropy) and
// buyers cannot snipe it (they do not know the secret). After the reveal
// everything needed to re-derive the salt is on chain, so VerifySeedSalt is
// a check anybody can run instead of a promise anybody has to believe.
//
// Until the reveal every token of the collection renders the same
// placeholder artwork and reports Status=Unrevealed.
//
// Committing is optional. A collection that never commits keeps exact v5.6
// behaviour - no salt, traits visible from the first block - and
// CollectionInfo.SaltCommit says which mode a collection is in, so a buyer
// never has to take the creator's word for which one they are looking at.
func CommitSeedSalt(cur realm, collectionID, commitHex string) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if caller != c.creator {
		panic("only the collection's creator can commit a seed salt")
	}
	if !c.generative {
		panic("seed salts only apply to generative collections; call SetGenerative first")
	}
	if c.saltCommit != "" {
		panic("this collection already has a seed salt commitment")
	}
	// A salt committed after the first mint would change the artwork of
	// tokens somebody already owns, which is the exact thing this realm
	// promises cannot happen.
	if c.mintedTotal > 0 {
		panic("collection already has minted tokens; a salt can only be committed before the first mint")
	}
	if len(commitHex) != 64 {
		panic("commitHex must be the 64-character hex sha256 of your secret")
	}
	lower := strings.ToLower(commitHex)
	if _, err := hex.DecodeString(lower); err != nil {
		panic("commitHex must be valid hex")
	}
	c.saltCommit = lower

	chain.Emit(
		"SeedSaltCommitted",
		"collection", collectionID,
		"commit", lower,
	)
}

// RevealSeedSalt publishes the secret behind the commitment and freezes the
// collection's final salt. Creator-only, and callable exactly once: the
// latch it sets can never be cleared, so the traits every buyer sees after
// the reveal are the traits that collection has forever.
//
// The gate is "supply minted out, or SaltRevealGraceBlocks have passed".
// Revealing earlier would hand the creator the map of every token still
// unminted, so the chain refuses instead of relying on restraint.
func RevealSeedSalt(cur realm, collectionID, secret string) string {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if caller != c.creator {
		panic("only the collection's creator can reveal the seed salt")
	}
	if c.saltCommit == "" {
		panic("this collection has no seed salt commitment to reveal")
	}
	if c.saltRevealed {
		panic("this collection's seed salt is already revealed and can never be changed")
	}
	if secret == "" || len(secret) > MaxSecretLen {
		panic("secret must be 1-" + strconv.Itoa(MaxSecretLen) + " characters")
	}
	if sha256Hex(secret) != c.saltCommit {
		panic("secret does not match this collection's commitment")
	}
	height := runtime.ChainHeight()
	// nextTokenID is the supply gate and only ever increases, so this stays
	// true even if every token has since been burned.
	soldOut := c.nextTokenID > c.maxSupply
	if !soldOut && height < c.createdAt+SaltRevealGraceBlocks {
		panic("the seed salt can only be revealed once the supply is minted out, or after the grace period")
	}

	c.seedSalt = saltFrom(secret, c.saltEntropy, c.id)
	c.saltSecret = secret
	c.saltRevealed = true
	c.saltRevealedAt = height
	c.saltRevealMinted = c.mintedTotal

	chain.Emit(
		"SeedSaltRevealed",
		"collection", collectionID,
		"salt", c.seedSalt,
		"secret", secret,
		"entropy", strconv.FormatInt(c.saltEntropy, 10),
		"minted", strconv.FormatInt(c.mintedTotal, 10),
	)

	return c.seedSalt
}

// VerifySeedSalt recomputes a revealed salt from the values stored on chain
// and reports whether the creator's reveal actually matches the commitment
// they published before the sale. A buyer runs this instead of trusting the
// reveal; it returns false for a collection that has not revealed yet.
func VerifySeedSalt(collectionID string) bool {
	return verifySalt(mustGetCollection(collectionID))
}

func verifySalt(c *Collection) bool {
	if !c.saltRevealed {
		return false
	}
	if sha256Hex(c.saltSecret) != c.saltCommit {
		return false
	}
	return c.seedSalt == saltFrom(c.saltSecret, c.saltEntropy, c.id)
}

// SeedSaltState is the one-call answer to "can I see the real art yet?":
// "none" (no commitment, traits always public), "pending" (committed,
// placeholder art) or "revealed".
func SeedSaltState(collectionID string) string {
	c := mustGetCollection(collectionID)
	switch {
	case c.saltCommit == "":
		return "none"
	case !c.saltRevealed:
		return "pending"
	default:
		return "revealed"
	}
}

// saltFrom binds both halves of the salt together: the creator's committed
// secret and the minters' accumulated entropy, plus the collection ID so
// the same secret reused on two collections cannot produce the same map.
func saltFrom(secret string, entropy int64, collectionID string) string {
	return sha256Hex(secret + "|" + strconv.FormatInt(entropy, 10) + "|" + collectionID)
}

// revealPending reports that a collection has a salt commitment whose
// secret is not public yet, which is what makes the read paths serve
// placeholder art instead of the real artwork.
func revealPending(c *Collection) bool {
	return c.generative && c.saltCommit != "" && !c.saltRevealed
}

// seedOf is the ONLY place a token's generative seed is produced. It
// returns "" while the salt is pending, so no read path, event or receipt
// can leak the trait map early by accident.
func seedOf(c *Collection, tokenID string) string {
	if revealPending(c) {
		return ""
	}
	return nftgen1.SeedForSalted(c.id, tokenID, c.seedSalt)
}

// preRevealURI is the placeholder artwork an un-revealed collection serves
// for every one of its tokens: on-chain, deterministic, and identical
// across tokens so nobody can read rarity out of it. It still differs per
// collection, so two pending drops do not look like the same one.
func preRevealURI(c *Collection) string {
	return nftgen1.DataURI(nftgen1.SeedFor(c.id, "prereveal"))
}

func sha256Hex(s string) string {
	sum := sha256.Sum256([]byte(s))
	return hex.EncodeToString(sum[:])
}

// mixEntropy folds one mint's inputs into the accumulator. splitmix64 is
// used for avalanche only - the unforgeable half of the salt is the sha256
// commitment, not this - which keeps a mint at a few arithmetic ops instead
// of a hash.
func mixEntropy(prev int64, minter address, height int64, tokenID string) int64 {
	h := uint64(prev)
	h = splitmix64(h ^ fnv64(minter.String()))
	h = splitmix64(h + uint64(height))
	h = splitmix64(h ^ fnv64(tokenID))
	return int64(h)
}

func fnv64(s string) uint64 {
	h := uint64(14695981039346656037)
	for i := 0; i < len(s); i++ {
		h ^= uint64(s[i])
		h *= 1099511628211
	}
	return h
}

func splitmix64(x uint64) uint64 {
	x += 0x9E3779B97F4A7C15
	x = (x ^ (x >> 30)) * 0xBF58476D1CE4E5B9
	x = (x ^ (x >> 27)) * 0x94D049BB133111EB
	return x ^ (x >> 31)
}

// QueuePresetURI appends one tokenURI to a collection's reveal queue.
// Creator-only.
func QueuePresetURI(cur realm, collectionID, uri string) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if caller != c.creator {
		panic("only the collection's creator can queue preset artwork")
	}
	if uri == "" {
		panic("uri must not be empty")
	}
	if len(uri) > MaxURILen {
		panic("uri too long")
	}
	assertSafeURI(uri, "uri")
	if int64(len(c.presetURIs)) >= c.maxSupply {
		panic("preset queue is already as large as the collection's max supply")
	}
	c.presetURIs = append(c.presetURIs, uri)
}

// SetBaseURI replaces a collection's baseURI exactly ONCE and then locks
// it forever. Creator-only.
//
// This is the reveal mechanic incoming creators expect: mint against a
// placeholder, then publish the real IPFS folder CID when the sale ends.
// The one-shot latch is the part that matters. On Ethereum setBaseURI stays
// callable for the contract's whole life, so a buyer's artwork can be
// rewritten after purchase; here the first call consumes the right, and
// because realms are immutable no later code can hand it back.
func SetBaseURI(cur realm, collectionID, baseURI string) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if caller != c.creator {
		panic("only the collection's creator can set its baseURI")
	}
	if c.baseURILocked {
		panic("this collection's baseURI is locked and can never be changed again")
	}
	if baseURI == "" {
		panic("baseURI must not be empty")
	}
	if len(baseURI) > MaxURILen {
		panic("baseURI too long")
	}
	assertSafeURI(baseURI, "baseURI")
	c.baseURI = baseURI
	c.baseURILocked = true
	chain.Emit(
		"BaseURIRevealed",
		"collection", collectionID,
		"baseURI", baseURI,
	)
}

// LockBaseURI freezes the baseURI without changing it, so a creator who
// needs no reveal can prove that on chain before selling anything.
// Creator-only and irreversible.
func LockBaseURI(cur realm, collectionID string) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if caller != c.creator {
		panic("only the collection's creator can lock its baseURI")
	}
	if c.baseURILocked {
		panic("this collection's baseURI is already locked")
	}
	c.baseURILocked = true
	chain.Emit("BaseURILocked", "collection", collectionID)
}

// SetCollectionURI points a collection at its collection-level metadata
// (banner, logo, links) - the OpenSea contractURI equivalent. Creator-only.
//
// Unlike baseURI this stays editable: it describes the storefront, not the
// asset anybody bought, so freezing it would only stop a creator from
// fixing a dead link.
func SetCollectionURI(cur realm, collectionID, uri string) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if caller != c.creator {
		panic("only the collection's creator can set its collection URI")
	}
	if len(uri) > MaxURILen {
		panic("uri too long")
	}
	assertSafeURI(uri, "uri")
	c.collectionURI = uri
}

// MintBatch mints count tokens of a collection to the caller in a single
// transaction and returns the minted IDs joined by ",".
//
// It exists because creators routinely pre-mint inventory before selling,
// and v5.5 charged them one transaction per token. This is a loop over the
// ordinary mint paths, not a privileged shortcut: supply, per-wallet cap,
// publicMint and generative mode are evaluated per token exactly as in a
// single mint, so a batch that would exceed any limit panics and the whole
// transaction reverts. count is capped at MaxMintBatch so one call cannot
// grow past the block gas limit.
func MintBatch(cur realm, collectionID string, count int64) string {
	return mintBatch(cur, callerOf(cur), collectionID, count)
}

// mintBatch is the shared batch path. The caller is resolved once by the
// exported entry point and threaded through, exactly as mintGenerativeOne
// does, so every token in a batch is attributed to the same identity the
// transaction was signed by and the loop cannot depend on the frame it runs
// in.
func mintBatch(cur realm, caller address, collectionID string, count int64) string {
	if count <= 0 {
		panic("count must be positive")
	}
	if count > MaxMintBatch {
		panic("count must be at most " + strconv.Itoa(MaxMintBatch) + " per call")
	}
	c := mustGetCollection(collectionID)
	var b strings.Builder
	for i := int64(0); i < count; i++ {
		var tidStr string
		if c.generative {
			tidStr = mintGenerativeOne(cur, caller, collectionID)
		} else {
			tidStr = mint(cur, caller, collectionID, "", "")
		}
		if i > 0 {
			b.WriteString(",")
		}
		b.WriteString(tidStr)
	}
	return b.String()
}

// SetMaxPerWallet sets (0 clears) the trustless per-wallet mint cap.
// Creator-only. Lowering it never retroactively invalidates existing
// tokens; it only blocks further mints by wallets already at or over it.
func SetMaxPerWallet(cur realm, collectionID string, max int64) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if caller != c.creator {
		panic("only the collection's creator can set its mint limit")
	}
	if max < 0 {
		panic("max must be >= 0 (0 clears the limit)")
	}
	c.maxPerWallet = max
}

// Approve approves `to` to transfer a single token on the caller's behalf.
func Approve(cur realm, collectionID, tokenID string, to address) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if err := c.token.Approve(caller, to, grc721.TokenID(tokenID)); err != nil {
		panic(err)
	}
}

// SetApprovalForAll grants/revokes operator permission across all of the
// caller's tokens in one collection (e.g. approving the marketplace realm
// once instead of per-token).
func SetApprovalForAll(cur realm, collectionID string, operator address, approved bool) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	if err := c.token.SetApprovalForAll(caller, operator, approved); err != nil {
		panic(err)
	}
}

// TransferFrom transfers a token from `from` to `to`. The caller must be
// the owner or an approved operator/spender — which is how nftmarket2 and
// nftoffers2 move tokens: they call this via cross(cur), so the caller
// seen here is the marketplace realm's own address, exactly the identity
// the seller approved.
func TransferFrom(cur realm, collectionID, tokenID string, from, to address) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	tid := grc721.TokenID(tokenID)

	if err := c.token.TransferFrom(caller, from, to, tid); err != nil {
		panic(err)
	}

	ownerIndex.Remove(from.String() + ":" + collectionID + ":" + tokenID)
	ownerIndex.Set(to.String()+":"+collectionID+":"+tokenID, true)

	chain.Emit(
		"Transfer",
		"collection", collectionID,
		"tokenId", tokenID,
		"from", from.String(),
		"to", to.String(),
	)
}

// Burn destroys a token. Caller must be the token's current owner. The
// burned token's supply slot is never reused.
func Burn(cur realm, collectionID, tokenID string) {
	caller := callerOf(cur)
	c := mustGetCollection(collectionID)
	tid := grc721.TokenID(tokenID)

	owner, err := c.token.OwnerOf(tid)
	if err != nil {
		panic(err)
	}
	if owner != caller {
		panic("only the token owner can burn it")
	}
	if err := c.token.Burn(tid); err != nil {
		panic(err)
	}

	ownerIndex.Remove(owner.String() + ":" + collectionID + ":" + tokenID)
	attributes.Remove(collectionID + ":" + tokenID)

	chain.Emit("Burn", "collection", collectionID, "tokenId", tokenID, "from", owner.String())
}

// Read-only views.

// GetCollection returns the exported view of one collection.
func GetCollection(collectionID string) CollectionInfo {
	return toInfo(mustGetCollection(collectionID))
}

// ListCollections returns up to `limit` collections starting at `offset`,
// ordered by collection ID (creation order).
func ListCollections(offset, limit int64) []CollectionInfo {
	out := make([]CollectionInfo, 0, limit)
	collections.IterateByOffset(int(offset), int(limit), func(key string, value any) bool {
		out = append(out, toInfo(value.(*Collection)))
		return false
	})
	return out
}

// CollectionCount returns the total number of collections ever created.
func CollectionCount() int64 {
	return collCount
}

// TokensOfOwner returns "collectionId:tokenId" pairs for every token the
// given address owns, across every collection in this realm.
func TokensOfOwner(owner address) []string {
	var out []string
	prefix := owner.String() + ":"
	ownerIndex.Iterate(prefix, owner.String()+";", func(key string, value any) bool {
		out = append(out, key[len(prefix):])
		return false
	})
	return out
}

// TokensOfCollection returns the live token IDs of one collection in
// ascending numeric order.
//
// v5.3 answered this from a dedicated "collectionId:paddedTokenId" index
// that every mint had to write. v5.4 derives it instead: token IDs are
// consecutive 1..nextTokenID-1 by construction (nextTokenID only ever
// increases and a burn never re-opens a slot), so the live set is exactly
// that range minus whatever grc721 no longer owns. Same answer, same
// order, one less storage write per mint (see package doc, v5.4 change 2).
//
// This is a read-only view, so the scan is paid for by the RPC query, not
// by a transaction. Nothing on a write path calls it.
func TokensOfCollection(collectionID string, offset, limit int64) []string {
	c := mustGetCollection(collectionID)
	var out []string
	var seen int64
	for id := int64(1); id < c.nextTokenID; id++ {
		if limit > 0 && int64(len(out)) >= limit {
			break
		}
		tidStr := strconv.FormatInt(id, 10)
		if _, err := c.token.OwnerOf(grc721.TokenID(tidStr)); err != nil {
			continue // burned
		}
		if seen < offset {
			seen++
			continue
		}
		out = append(out, tidStr)
		seen++
	}
	return out
}

// MintedByWallet returns how many tokens of a collection an address has
// minted over its lifetime (the number the per-wallet cap is checked
// against — not the same as the current balance).
//
// v5.4 only keeps this counter for collections that actually set a cap,
// so an uncapped collection reports 0 here. That is not a lost limit:
// with maxPerWallet == 0 there is nothing to enforce, and the UI already
// treats "no cap" as unlimited rather than comparing against this number.
func MintedByWallet(collectionID string, wallet address) int64 {
	return mintedByWallet(mustGetCollection(collectionID), wallet)
}

// BalanceOf returns how many tokens of one collection an address owns.
func BalanceOf(collectionID string, owner address) int64 {
	bal, err := mustGetCollection(collectionID).token.BalanceOf(owner)
	if err != nil {
		panic(err)
	}
	return bal
}

// OwnerOf returns the current owner of a token.
func OwnerOf(collectionID, tokenID string) (address, error) {
	return mustGetCollection(collectionID).token.OwnerOf(grc721.TokenID(tokenID))
}

// TokenURI returns the metadata URI of a token, resolving in this order:
//
//  1. generative collection -> the data: URI nftgen1 rebuilds from the
//     token's derived seed. Nothing is stored at all: storing a 4-5 KB
//     base64 SVG per token cost roughly 2.1 GNOT of deposit in v4, and
//     because the generator is deterministic the artwork is
//     byte-identical forever.
//  2. a URI stored for this specific token -> that URI.
//  3. the collection's baseURI -> baseURI + tokenID.
//
// Step 3 is v5.7's whole point for incoming creators (package doc, v5.7
// change 1): an IPFS folder CID is written once at collection level and
// every token derives its URI from it, exactly as ERC-721 collections do,
// instead of paying one transaction per token.
func TokenURI(collectionID, tokenID string) (string, error) {
	c := mustGetCollection(collectionID)
	// Gate on existence first, so a burned or never-minted token reports an
	// error instead of quietly resolving to a plausible-looking baseURI.
	if _, err := c.token.OwnerOf(grc721.TokenID(tokenID)); err != nil {
		return "", err
	}
	if c.generative {
		if revealPending(c) {
			return preRevealURI(c), nil
		}
		return nftgen1.DataURI(seedOf(c, tokenID)), nil
	}
	uri, err := c.token.TokenURI(grc721.TokenID(tokenID))
	if err == nil && uri != "" {
		return uri, nil
	}
	if c.baseURI != "" {
		return c.baseURI + tokenID, nil
	}
	return uri, err
}

// TokenSeed returns the generative seed of a token, or "" when the token
// is not generative or does not exist.
//
// The seed is derived, not stored (package doc, v5.7 change 3). The answer
// is byte-identical to what v5.5 persisted, because what v5.5 persisted was
// nftgen1.SeedFor(collectionID, tokenID) itself.
func TokenSeed(collectionID, tokenID string) string {
	c := mustGetCollection(collectionID)
	if !c.generative {
		return ""
	}
	if _, err := c.token.OwnerOf(grc721.TokenID(tokenID)); err != nil {
		return ""
	}
	return seedOf(c, tokenID)
}

// TokenAttributes returns a token's traits.
//
// Stored traits win when they exist, so tokens minted with explicit traits
// (and any token carried over from an older realm) keep behaving exactly as
// before. A generative token has none: its traits are rebuilt here from its
// seed, which is both cheaper and unforgeable - see package doc, changes A
// and B. The output is byte-identical to what v5 used to persist, which the
// realm's test suite asserts seed by seed.
func TokenAttributes(collectionID, tokenID string) []Attribute {
	if v := avlGet(attributes, collectionID+":"+tokenID); v != nil {
		return v.([]Attribute)
	}
	c := mustGetCollection(collectionID)
	if c.generative {
		if _, err := c.token.OwnerOf(grc721.TokenID(tokenID)); err == nil {
			if revealPending(c) {
				// One honest trait instead of nil, so a marketplace shows
				// "Unrevealed" rather than an empty trait panel that looks
				// like a broken token.
				return []Attribute{{TraitType: "Status", Value: "Unrevealed"}}
			}
			return deriveAttributes(seedOf(c, tokenID))
		}
	}
	return nil
}

// deriveAttributes rebuilds the trait list for a seed. It mirrors
// nftgen1.TraitString field for field; the test suite pins that equality
// so the two can never drift apart silently.
//
// nftgen1 has ten fields where nftgen1 had seven: Frame, Finish and a
// four-step Aura replace gen0's yes/no Aura, and Score is exposed so a
// marketplace can sort by rarity weight instead of by the Rarity label
// alone. Ten is still well inside MaxAttributesPerToken.
func deriveAttributes(seed string) []Attribute {
	tr := nftgen1.TraitsOf(seed)
	return []Attribute{
		{TraitType: "Palette", Value: tr.Palette},
		{TraitType: "Shape", Value: tr.Shape},
		{TraitType: "Ground", Value: tr.Ground},
		{TraitType: "Frame", Value: tr.Frame},
		{TraitType: "Finish", Value: tr.Finish},
		{TraitType: "Aura", Value: tr.Aura},
		{TraitType: "Elements", Value: strconv.Itoa(tr.Elements)},
		{TraitType: "Symmetry", Value: strconv.Itoa(tr.Symmetry)},
		{TraitType: "Score", Value: strconv.Itoa(tr.Score)},
		{TraitType: "Rarity", Value: tr.Rarity},
	}
}

// TokenMetadata assembles a complete metadata JSON document for a token
// inside the realm, so a fully on-chain token needs no IPFS, no gateway
// and no pinning service to be readable.
func TokenMetadata(collectionID, tokenID string) string {
	c := mustGetCollection(collectionID)
	uri, err := TokenURI(collectionID, tokenID)
	if err != nil {
		panic(err)
	}
	_ = c

	out := "{\"name\":\"" + jsonEscape(c.name+" #"+tokenID) + "\""
	out += ",\"description\":\"" + jsonEscape(c.description) + "\""
	out += ",\"image\":\"" + jsonEscape(uri) + "\""
	out += ",\"attributes\":["
	for i, a := range TokenAttributes(collectionID, tokenID) {
		if i > 0 {
			out += ","
		}
		out += "{\"trait_type\":\"" + jsonEscape(a.TraitType) +
			"\",\"value\":\"" + jsonEscape(a.Value) + "\"}"
	}
	out += "]}"
	return out
}

// GetApproved returns the address approved for a single token, if any.
func GetApproved(collectionID, tokenID string) (address, error) {
	return mustGetCollection(collectionID).token.GetApproved(grc721.TokenID(tokenID))
}

// IsApprovedForAll reports whether operator can manage all of owner's
// tokens in one collection.
func IsApprovedForAll(collectionID string, owner, operator address) bool {
	return mustGetCollection(collectionID).token.IsApprovedForAll(owner, operator)
}

// RoyaltyInfo returns the payment address and royalty amount owed for a
// sale of the given token at salePrice.
//
// v5.4 computes this from the collection record instead of a per-token
// royalty row (package doc, v5.4 change 1). Every token in a collection
// always had the identical (creator, royaltyPct) pair written into it at
// mint time, because royaltyPct is fixed at CreateCollection and nothing
// can rewrite it afterwards — so the per-token copy was pure duplication.
// The guarantee the market cares about is unchanged: the royalty a buyer
// pays is decided by the collection's immutable terms, not by whoever
// happens to hold the token.
func RoyaltyInfo(collectionID, tokenID string, salePrice int64) (address, int64, error) {
	c := mustGetCollection(collectionID)
	// Still gate on existence, so a sale of a burned/never-minted token
	// cannot quietly report "no royalty owed" the way a missing row would.
	if _, err := c.token.OwnerOf(grc721.TokenID(tokenID)); err != nil {
		return "", 0, err
	}
	if c.royaltyPct <= 0 {
		return "", 0, nil
	}
	return c.creator, salePrice * c.royaltyPct / 100, nil
}

// Render implements the gno.land realm home-page convention so the
// factory is browsable from gnoweb even without the dedicated frontend.
func Render(path string) string {
	if path != "" {
		v := avlGet(collections, path)
		if v == nil {
			return "# 404\n\ncollection not found: " + path
		}
		return renderCollection(v.(*Collection))
	}

	out := ufmt.Sprintf("# gnoNFT Factory v5.4\n\n%d collection(s)\n\n", collCount)
	collections.Iterate("", "", func(key string, value any) bool {
		c := value.(*Collection)
		out += ufmt.Sprintf(
			"- [#%s %s (%s)](:%s) - %d/%d minted, by %s\n",
			c.id, c.name, c.symbol, c.id, c.mintedTotal, c.maxSupply, c.creator.String(),
		)
		return false
	})
	return out
}

func renderCollection(c *Collection) string {
	out := ufmt.Sprintf("# %s (%s)\n\n%s\n\n", c.name, c.symbol, c.description)
	out += ufmt.Sprintf("- Creator: %s\n", c.creator.String())
	out += ufmt.Sprintf("- Minted: %d / %d\n", c.mintedTotal, c.maxSupply)
	out += ufmt.Sprintf("- Currently live: %d\n", c.token.TokenCount())
	out += ufmt.Sprintf("- Public mint: %t\n", c.publicMint)
	out += ufmt.Sprintf("- Royalty: %d%%\n", c.royaltyPct)
	if c.generative {
		switch {
		case c.saltCommit == "":
			out += "- Seed salt: none (traits public since the first mint)\n"
		case !c.saltRevealed:
			out += ufmt.Sprintf("- Seed salt: committed, NOT revealed yet (commit %s)\n", c.saltCommit)
		default:
			out += ufmt.Sprintf("- Seed salt: revealed at height %d, %d minted (verified: %t)\n",
				c.saltRevealedAt, c.saltRevealMinted, verifySalt(c))
		}
	}
	if c.maxPerWallet > 0 {
		out += ufmt.Sprintf("- Max per wallet: %d\n", c.maxPerWallet)
	}
	if total := len(c.presetURIs); total > 0 {
		out += ufmt.Sprintf("- Presets revealed: %d / %d\n", c.presetNext, total)
	}
	return out
}

// Internal helpers.

func mintedByWallet(c *Collection, wallet address) int64 {
	v := avlGet(c.mintedBy, wallet.String())
	if v == nil {
		return 0
	}
	return v.(int64)
}

// parseTraits turns "Background=Blue;Eyes=Laser" into attributes. Empty
// segments are skipped; a segment with no '=' is rejected outright rather
// than silently stored, so a typo can't be minted into a token forever.
func parseTraits(traits string) []Attribute {
	if traits == "" {
		return nil
	}
	var out []Attribute
	for _, seg := range strings.Split(traits, ";") {
		seg = strings.TrimSpace(seg)
		if seg == "" {
			continue
		}
		idx := strings.Index(seg, "=")
		if idx <= 0 || idx == len(seg)-1 {
			panic("malformed trait \"" + seg + "\": expected trait=value pairs separated by ';'")
		}
		k := strings.TrimSpace(seg[:idx])
		v := strings.TrimSpace(seg[idx+1:])
		if len(k) > MaxTraitLen || len(v) > MaxTraitLen {
			panic("trait name/value too long (max " + strconv.Itoa(MaxTraitLen) + " chars)")
		}
		out = append(out, Attribute{TraitType: k, Value: v})
		if len(out) > MaxAttributesPerToken {
			panic("too many traits (max " + strconv.Itoa(MaxAttributesPerToken) + ")")
		}
	}
	return out
}

func jsonEscape(s string) string {
	var b strings.Builder
	for _, r := range s {
		switch r {
		case '"':
			b.WriteString("\\\"")
		case '\\':
			b.WriteString("\\\\")
		case '\n':
			b.WriteString("\\n")
		case '\r':
			b.WriteString("\\r")
		case '\t':
			b.WriteString("\\t")
		default:
			if r < 0x20 {
				const hexDigits = "0123456789abcdef"
				b.WriteString("\\u00")
				b.WriteByte(hexDigits[(r>>4)&0xf])
				b.WriteByte(hexDigits[r&0xf])
				continue
			}
			b.WriteRune(r)
		}
	}
	return b.String()
}

func toInfo(c *Collection) CollectionInfo {
	presetsTotal := int64(len(c.presetURIs))
	remaining := presetsTotal - int64(c.presetNext)
	if remaining < 0 {
		remaining = 0
	}
	return CollectionInfo{
		ID:               c.id,
		Name:             c.name,
		Symbol:           c.symbol,
		Description:      c.description,
		BaseURI:          c.baseURI,
		Creator:          c.creator,
		MaxSupply:        c.maxSupply,
		Minted:           c.token.TokenCount(),
		MintedTotal:      c.mintedTotal,
		PublicMint:       c.publicMint,
		RoyaltyPct:       c.royaltyPct,
		MaxPerWallet:     c.maxPerWallet,
		PresetsTotal:     presetsTotal,
		PresetsRemaining: remaining,
		CreatedAt:        c.createdAt,
		OnchainTokens:    c.onchainTokens,
		IpfsTokens:       c.ipfsTokens,
		StorageKind:      storageKind(c),
		Generative:       c.generative,
		Engine:           c.engine,
		CollectionURI:    c.collectionURI,
		BaseURILocked:    c.baseURILocked,
		SaltCommit:       c.saltCommit,
		SaltPending:      revealPending(c),
		SaltRevealed:     c.saltRevealed,
		SeedSalt:         c.seedSalt,
		SaltSecret:       c.saltSecret,
		SaltEntropy:      c.saltEntropy,
		SaltRevealedAt:   c.saltRevealedAt,
		SaltRevealMinted: c.saltRevealMinted,
	}
}

// storageKind reports where a collection's artwork lives:
//
//	"onchain"  every minted token is a data: URI - nothing off-chain to rot
//	"ipfs"     every minted token points at ipfs://
//	"external" plain http(s) links
//	"mixed"    a bit of both
//	"unknown"  nothing minted yet and no baseURI hint
//
// Before the first mint the baseURI is the only evidence available, so it
// is used as the hint; after that the per-token counters decide.
func storageKind(c *Collection) string {
	if c.mintedTotal == 0 {
		if strings.HasPrefix(c.baseURI, "data:") {
			return "onchain"
		}
		if strings.HasPrefix(c.baseURI, "ipfs://") {
			return "ipfs"
		}
		if c.baseURI == "" {
			return "unknown"
		}
		return "external"
	}
	if c.onchainTokens == c.mintedTotal {
		return "onchain"
	}
	if c.ipfsTokens == c.mintedTotal {
		return "ipfs"
	}
	if c.onchainTokens == 0 && c.ipfsTokens == 0 {
		return "external"
	}
	return "mixed"
}

// CollectionStorageKind exposes storageKind as a standalone view so the UI
// can badge a collection without decoding a whole CollectionInfo.
func CollectionStorageKind(collectionID string) string {
	return storageKind(mustGetCollection(collectionID))
}

// assertNotGenerative refuses hand-minting into a generative collection, so
// "every token here is derived from its seed" stays a checkable claim.
func assertNotGenerative(collectionID string) {
	if mustGetCollection(collectionID).generative {
		panic("this collection is generative; use MintGenerative")
	}
}

// assertSafeURI refuses artwork URIs that a wallet, explorer or the
// frontend could be tricked into executing. A tokenURI is rendered by
// every client that shows the collection, so a "javascript:" or
// "data:text/html" payload minted into a public collection is stored XSS
// that would live on chain forever. Only schemes that can be rendered as
// an image or parsed as metadata are accepted.
func assertSafeURI(uri, label string) {
	if uri == "" {
		return
	}
	lower := strings.ToLower(uri)
	if strings.HasPrefix(lower, "https://") ||
		strings.HasPrefix(lower, "ipfs://") ||
		strings.HasPrefix(lower, "ar://") ||
		strings.HasPrefix(lower, "data:image/") ||
		strings.HasPrefix(lower, "data:application/json") {
		return
	}
	panic(label + " must start with https://, ipfs://, ar://, data:image/ or data:application/json")
}

func mustGetCollection(id string) *Collection {
	v := avlGet(collections, id)
	if v == nil {
		panic("collection not found: " + id)
	}
	return v.(*Collection)
}

package nft57

import (
	"strings"
	"testing"

	"gno.land/p/nt/uassert/v0"
	"gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nftgen1"
)

// NOTE: minting needs a direct wallet call, so the CreateCollection/Mint
// paths are exercised on chain on Pearl. What is pinned here is the v5.2
// change itself: derived traits must be byte-identical to the traits v5
// used to persist, deriving must be free of stored state, and the new
// anti-spoofing rules must actually refuse the calls they claim to refuse.

// TestDerivedTraitsMatchStoredTraits is the anti-drift proof: for a spread
// of seeds, what this realm reports as a token's traits must be exactly
// what the engine itself says, pair for pair, in the same order.
//
// nftgen1.TraitString carries nine pairs; deriveAttributes adds Score as a
// tenth so a marketplace can sort by rarity weight. The nine shared pairs
// are compared field for field, and Score is pinned separately as the only
// permitted extra - so neither the engine nor this realm can change a trait
// name, a value or the order without this test failing.
func TestDerivedTraitsMatchStoredTraits(t *testing.T) {
	cases := []string{"1:1", "1:2", "1:7", "2:1", "3:42", "9:1000", "gen1:5"}
	for _, seed := range cases {
		engine := parseTraits(nftgen1.TraitString(seed))
		derived := deriveAttributes(seed)
		uassert.Equal(t, 9, len(engine))
		uassert.Equal(t, 10, len(derived))

		// Score sits between Symmetry and Rarity, so the shared pairs line
		// up one-to-one up to it and shift by one after it.
		for i := 0; i < 8; i++ {
			uassert.Equal(t, engine[i].TraitType, derived[i].TraitType)
			uassert.Equal(t, engine[i].Value, derived[i].Value)
		}
		uassert.Equal(t, "Score", derived[8].TraitType)
		uassert.Equal(t, "Rarity", derived[9].TraitType)
		uassert.Equal(t, engine[8].Value, derived[9].Value)
	}
}

// TestDerivedTraitsAreWellFormed keeps the derived list inside the same
// bounds the stored list had to respect.
func TestDerivedTraitsAreWellFormed(t *testing.T) {
	attrs := deriveAttributes(nftgen1.SeedFor("1", "3"))
	uassert.Equal(t, 10, len(attrs))
	uassert.True(t, len(attrs) <= MaxAttributesPerToken)
	for _, a := range attrs {
		uassert.True(t, a.TraitType != "")
		uassert.True(t, a.Value != "")
		uassert.True(t, len(a.TraitType) <= MaxTraitLen)
		uassert.True(t, len(a.Value) <= MaxTraitLen)
	}
}

// TestTokenAttributesDerivesFromSeedOnly proves nothing has to be stored in
// the attributes tree for a generative token to report its traits, and that
// the derivation is stable across reads.
func TestTokenAttributesDerivesFromSeedOnly(cur realm, t *testing.T) {
	c := newTestCollection(cur, "700", 0, 0)
	defer dropTestCollection("700")
	c.generative = true
	c.engine = Engine
	mintGenerativeOne(cur, testBuyer, "700")

	// v5.7 stores NEITHER the traits nor the seed: both trees stay empty
	// and the answer is still complete (package doc, v5.7 change 3).
	uassert.Equal(t, nil, avlGet(attributes, "700:1"))

	first := TokenAttributes("700", "1")
	second := TokenAttributes("700", "1")
	uassert.Equal(t, 10, len(first))
	uassert.Equal(t, len(first), len(second))
	for i := range first {
		uassert.Equal(t, first[i].Value, second[i].Value)
	}

	// A token that was never minted reports no traits rather than deriving
	// traits for art that does not exist.
	uassert.Equal(t, 0, len(TokenAttributes("700", "2")))

	// And a non-generative collection never derives.
	c.generative = false
	uassert.Equal(t, 0, len(TokenAttributes("700", "1")))
}

// TestStoredAttributesWinOverDerived protects tokens that carry hand-written
// traits (and anything carried over from an older realm): the seed path must
// never overwrite what is actually stored.
func TestStoredAttributesWinOverDerived(cur realm, t *testing.T) {
	c := newTestCollection(cur, "800", 0, 0)
	defer dropTestCollection("800")
	c.generative = true
	c.engine = Engine
	mintGenerativeOne(cur, testBuyer, "800")

	attributes.Set("800:1", []Attribute{{TraitType: "Hand", Value: "Written"}})

	attrs := TokenAttributes("800", "1")
	uassert.Equal(t, 1, len(attrs))
	uassert.Equal(t, "Hand", attrs[0].TraitType)
	uassert.Equal(t, "Written", attrs[0].Value)

	attributes.Remove("800:1")
}

// TestSeedBackedTokenURI carries the v5 guarantee forward: no blob stored,
// full artwork served, byte-identical on every read.
func TestSeedBackedTokenURI(cur realm, t *testing.T) {
	c := newTestCollection(cur, "400", 0, 0)
	defer dropTestCollection("400")
	c.generative = true
	c.engine = Engine
	mintGenerativeOne(cur, testBuyer, "400")

	seed := nftgen1.SeedFor("400", "1")
	uri, err := TokenURI("400", "1")
	uassert.NoError(t, err)
	uassert.True(t, strings.HasPrefix(uri, "data:"))
	uassert.Equal(t, nftgen1.DataURI(seed), uri)

	again, err := TokenURI("400", "1")
	uassert.NoError(t, err)
	uassert.Equal(t, uri, again)

	uassert.Equal(t, seed, TokenSeed("400", "1"))
	// Never-minted token: no seed, no art.
	uassert.Equal(t, "", TokenSeed("400", "2"))
}

// TestDifferentTokensGetDifferentArt guards against a seed derivation that
// collapses to one image per collection.
func TestDifferentTokensGetDifferentArt(t *testing.T) {
	a := nftgen1.SeedFor("4", "1")
	b := nftgen1.SeedFor("4", "2")
	uassert.True(t, a != b)
	uassert.True(t, nftgen1.DataURI(a) != nftgen1.DataURI(b))
	uassert.True(t, deriveAttributes(a)[9].Value != "")
}

// TestEngineConstantIsAConcreteRealmPath pins the engine pinning itself: an
// empty or relative engine path would make the provenance claim meaningless.
func TestEngineConstantIsAConcreteRealmPath(t *testing.T) {
	uassert.True(t, strings.HasPrefix(Engine, "gno.land/r/"))
	uassert.True(t, strings.HasSuffix(Engine, "/nftgen1"))
}

// TestParseTraitsStillGuardsUserInput makes sure closing the spoofing hole
// did not quietly remove the input validation that hand-written traits still
// have to pass.
func TestParseTraitsStillGuardsUserInput(cur realm, t *testing.T) {
	uassert.Equal(t, 0, len(parseTraits("")))

	ok := parseTraits("Background=Blue;Eyes=Laser")
	uassert.Equal(t, 2, len(ok))
	uassert.Equal(t, "Background", ok[0].TraitType)
	uassert.Equal(t, "Laser", ok[1].Value)

	uassert.PanicsWithMessage(t, cur,
		"malformed trait \"nope\": expected trait=value pairs separated by ';'",
		func() { parseTraits("nope") })

	long := strings.Repeat("x", MaxTraitLen+1)
	uassert.PanicsWithMessage(t, cur,
		"trait name/value too long (max 64 chars)",
		func() { parseTraits("K=" + long) })
}

// TestAssertNotGenerativeRefusesHandMinting covers the new guard without
// needing a wallet call: a generative collection must reject hand minting.
func TestAssertNotGenerativeRefusesHandMinting(cur realm, t *testing.T) {
	c := &Collection{id: "99", generative: true, engine: Engine}
	collections.Set("99", c)

	uassert.PanicsWithMessage(t, cur,
		"this collection is generative; use MintGenerative",
		func() { assertNotGenerative("99") })

	c.generative = false
	assertNotGenerative("99") // must not panic once the flag is off

	collections.Remove("99")
}

package nft57

import (
	"testing"

	"gno.land/p/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/tokens/grc721"
	"gno.land/p/nt/uassert/v0"
)

// The per-wallet mint cap is the whole fairness story of a free-mint drop:
// if one wallet can take 50 of 1000 pieces, the "1 per person" promise on
// the mint page is decoration. So it is enforced in the realm, not in the
// UI, and it is pinned here for the two values a drop actually uses (1 and
// 2) plus the uncapped case.
//
// The cap is chosen at collection creation time (CreateCollection's
// maxPerWallet argument, 0 = unlimited) and counted over LIFETIME mints,
// which is why burning or transferring away cannot buy a wallet a second
// turn.

// TestCreateCollectionTakesTheCapAtCreation proves the cap is a creation-time
// decision that lands on the collection and is readable back, so a mint page
// can display the real rule rather than a hardcoded claim.
func TestCreateCollectionTakesTheCapAtCreation(cur realm, t *testing.T) {
	one := newTestCollection(cur, "620", 0, 1)
	defer dropTestCollection("620")
	two := newTestCollection(cur, "621", 0, 2)
	defer dropTestCollection("621")
	free := newTestCollection(cur, "622", 0, 0)
	defer dropTestCollection("622")

	uassert.Equal(t, int64(1), one.maxPerWallet)
	uassert.Equal(t, int64(2), two.maxPerWallet)
	uassert.Equal(t, int64(0), free.maxPerWallet)

	// Same values through the public read the frontend uses.
	uassert.Equal(t, int64(1), GetCollection("620").MaxPerWallet)
	uassert.Equal(t, int64(2), GetCollection("621").MaxPerWallet)
	uassert.Equal(t, int64(0), GetCollection("622").MaxPerWallet)

	// A nonsense cap is refused at creation rather than silently coerced.
	uassert.PanicsWithMessage(t, cur,
		"maxPerWallet must be >= 0 (0 means unlimited)",
		func() { CreateCollection(cur, "Bad", "BAD", "", "", 10, 0, -1, true) })
}

// TestCapOfOneAllowsExactlyOne is the OG drop's rule: one wallet, one piece.
func TestCapOfOneAllowsExactlyOne(cur realm, t *testing.T) {
	newTestCollection(cur, "623", 0, 1)
	defer dropTestCollection("623")

	mint(cur, testBuyer, "623", "", "")
	uassert.Equal(t, int64(1), MintedByWallet("623", testBuyer))

	uassert.PanicsWithMessage(t, cur,
		"wallet has reached this collection's per-wallet mint limit of 1",
		func() { mint(cur, testBuyer, "623", "", "") })

	// The cap is per wallet, not per collection: everyone else is unaffected.
	mint(cur, testCreator, "623", "", "")
	uassert.Equal(t, int64(1), MintedByWallet("623", testCreator))
	uassert.Equal(t, int64(2), GetCollection("623").MintedTotal)
}

// TestCapOfTwoAllowsExactlyTwo covers the other value a drop realistically
// picks, including the boundary: the second mint must still be allowed.
func TestCapOfTwoAllowsExactlyTwo(cur realm, t *testing.T) {
	newTestCollection(cur, "624", 0, 2)
	defer dropTestCollection("624")

	mint(cur, testBuyer, "624", "", "")
	mint(cur, testBuyer, "624", "", "") // boundary: allowed
	uassert.Equal(t, int64(2), MintedByWallet("624", testBuyer))

	uassert.PanicsWithMessage(t, cur,
		"wallet has reached this collection's per-wallet mint limit of 2",
		func() { mint(cur, testBuyer, "624", "", "") })
}

// TestCapSurvivesBurn is the reason the counter exists as its own number
// instead of being derived from the live balance: burning must not hand the
// wallet a fresh turn.
func TestCapSurvivesBurn(cur realm, t *testing.T) {
	c := newTestCollection(cur, "625", 0, 1)
	defer dropTestCollection("625")

	mint(cur, testBuyer, "625", "", "")
	uassert.NoError(t, c.token.Burn(grc721.TokenID("1")))

	// Balance is back to zero, the lifetime count is not.
	uassert.Equal(t, int64(1), MintedByWallet("625", testBuyer))
	uassert.PanicsWithMessage(t, cur,
		"wallet has reached this collection's per-wallet mint limit of 1",
		func() { mint(cur, testBuyer, "625", "", "") })
}

// TestCapSurvivesTransferAway closes the same hole from the other side: a
// wallet that moves its piece to a friend has still used its allocation.
func TestCapSurvivesTransferAway(cur realm, t *testing.T) {
	c := newTestCollection(cur, "626", 0, 1)
	defer dropTestCollection("626")

	mint(cur, testBuyer, "626", "", "")
	uassert.NoError(t, c.token.TransferFrom(testBuyer, testBuyer, testCreator, grc721.TokenID("1")))

	uassert.Equal(t, int64(1), MintedByWallet("626", testBuyer))
	uassert.PanicsWithMessage(t, cur,
		"wallet has reached this collection's per-wallet mint limit of 1",
		func() { mint(cur, testBuyer, "626", "", "") })
}

// TestUncappedCollectionWritesNoCounter is the fee half of the feature: a
// collection with no cap must not pay for a per-wallet AVL node nothing ever
// reads (v5.4 change 3). This is what keeps an uncapped mint cheap.
func TestUncappedCollectionWritesNoCounter(cur realm, t *testing.T) {
	c := newTestCollection(cur, "627", 0, 0)
	defer dropTestCollection("627")

	mint(cur, testBuyer, "627", "", "")
	mint(cur, testBuyer, "627", "", "")
	mint(cur, testBuyer, "627", "", "")

	uassert.Equal(t, 0, c.mintedBy.Size())
	uassert.Equal(t, int64(0), MintedByWallet("627", testBuyer))
	uassert.Equal(t, int64(3), c.mintedTotal)
}

// TestCapAppliesToGenerativeMints makes sure the OG (generative) path is
// capped by the same rule as a hand/IPFS mint - the free-mint drop runs on
// exactly this path.
func TestCapAppliesToGenerativeMints(cur realm, t *testing.T) {
	c := newTestCollection(cur, "628", 0, 1)
	defer dropTestCollection("628")
	c.generative = true
	c.engine = Engine

	mintGenerativeOne(cur, testBuyer, "628")
	uassert.PanicsWithMessage(t, cur,
		"wallet has reached this collection's per-wallet mint limit of 1",
		func() { mintGenerativeOne(cur, testBuyer, "628") })
}

// TestCapBoundsMintBatch is the one that matters most for v5.7: batching
// must not be a way to buy 25 pieces of a 1-per-wallet drop.
func TestCapBoundsMintBatch(cur realm, t *testing.T) {
	newTestCollection(cur, "629", 0, 1)
	defer dropTestCollection("629")
	uassert.PanicsWithMessage(t, cur,
		"wallet has reached this collection's per-wallet mint limit of 1",
		func() { mintBatch(cur, testBuyer, "629", 2) })

	// A cap of 2 permits a batch of exactly 2, and nothing beyond it.
	c := newTestCollection(cur, "630", 0, 2)
	defer dropTestCollection("630")
	uassert.Equal(t, "1,2", mintBatch(cur, testBuyer, "630", 2))
	uassert.Equal(t, int64(2), c.mintedTotal)
	uassert.PanicsWithMessage(t, cur,
		"wallet has reached this collection's per-wallet mint limit of 2",
		func() { mintBatch(cur, testBuyer, "630", 1) })
}

// TestSetMaxPerWalletCanTightenLater covers the creator who launches
// uncapped and then wants a cap: already-minted wallets keep their pieces,
// but the new rule applies from that moment on.
func TestSetMaxPerWalletCanTightenLater(cur realm, t *testing.T) {
	c := newTestCollection(cur, "631", 0, 0)
	defer dropTestCollection("631")
	c.creator = callerOf(cur)

	mint(cur, testBuyer, "631", "", "")
	mint(cur, testBuyer, "631", "", "")

	SetMaxPerWallet(cur, "631", 1)
	uassert.Equal(t, int64(1), GetCollection("631").MaxPerWallet)

	// The two existing tokens are untouched...
	uassert.Equal(t, int64(2), c.mintedTotal)
	// ...but the counter was never written while uncapped, so this wallet
	// still has its allocation. That is a deliberate, documented trade-off:
	// a cap added after the fact is forward-looking only.
	mint(cur, testBuyer, "631", "", "")
	uassert.PanicsWithMessage(t, cur,
		"wallet has reached this collection's per-wallet mint limit of 1",
		func() { mint(cur, testBuyer, "631", "", "") })
}

package nft57

import (
	"strings"
	"testing"

	"gno.land/p/nt/uassert/v0"
	"gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nftgen1"
)

// These tests cover v5.7's only behavioural change: the per-collection seed
// salt decided by commit-reveal.
//
// The property being defended is narrow and checkable: before the reveal,
// nobody - creator included - can know which token carries which traits;
// after the reveal, anybody can re-derive the salt from chain data and
// verify that the creator revealed the secret they committed to. Each test
// below is one half of that claim.

// TestSaltHashIsRealSha256 pins the hash itself against the published
// FIPS-180 vector. The commitment is only binding if it is a real
// pre-image-resistant hash: with an invertible mixer (fnv, splitmix) a
// creator could produce a second secret for the same commitment after
// seeing the entropy, and the whole scheme would be theatre.
func TestSaltHashIsRealSha256(t *testing.T) {
	uassert.Equal(t,
		"ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad",
		sha256Hex("abc"))
	uassert.Equal(t,
		"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",
		sha256Hex(""))
	uassert.Equal(t, 64, len(sha256Hex("anything")))
}

// TestSaltFromBindsBothHalves proves the final salt depends on the creator's
// secret AND the minters' entropy AND the collection ID, so neither party
// alone determines it and a secret reused on a second collection cannot
// reproduce the same trait map.
func TestSaltFromBindsBothHalves(t *testing.T) {
	base := saltFrom("secret", 42, "1")
	uassert.Equal(t, base, saltFrom("secret", 42, "1"))
	uassert.True(t, base != saltFrom("secret", 43, "1"))
	uassert.True(t, base != saltFrom("secret", 42, "2"))
	uassert.True(t, base != saltFrom("secrez", 42, "1"))
}

// TestMixEntropyIsDeterministicAndSensitive keeps the accumulator honest:
// replayable from chain data (so the reveal can be verified) but changed by
// every input a mint contributes.
func TestMixEntropyIsDeterministicAndSensitive(t *testing.T) {
	base := mixEntropy(0, testBuyer, 100, "1")
	uassert.Equal(t, base, mixEntropy(0, testBuyer, 100, "1"))
	uassert.True(t, base != mixEntropy(0, testBuyer, 101, "1"))
	uassert.True(t, base != mixEntropy(0, testBuyer, 100, "2"))
	uassert.True(t, base != mixEntropy(0, testCreator, 100, "1"))
	uassert.True(t, base != mixEntropy(base, testBuyer, 100, "1"))
}

// TestUncommittedCollectionKeepsV56Behaviour is the compatibility half: a
// creator who never commits a salt gets exactly the v5.6 collection, traits
// public from the first block, and pays nothing for a feature they did not
// ask for.
func TestUncommittedCollectionKeepsV56Behaviour(cur realm, t *testing.T) {
	c := newTestCollection(cur, "900", 0, 0)
	defer dropTestCollection("900")
	c.generative = true
	c.engine = Engine

	mintGenerativeOne(cur, testBuyer, "900")

	uassert.Equal(t, "none", SeedSaltState("900"))
	uassert.False(t, revealPending(c))
	uassert.Equal(t, "900:1", TokenSeed("900", "1"))
	uassert.Equal(t, 10, len(TokenAttributes("900", "1")))

	uri, err := TokenURI("900", "1")
	uassert.NoError(t, err)
	uassert.Equal(t, nftgen1.DataURI(nftgen1.SeedFor("900", "1")), uri)

	// No commitment means no entropy bookkeeping at all.
	uassert.Equal(t, int64(0), c.saltEntropy)
}

// TestPendingSaltHidesSeedTraitsAndArt is the anti-sniping half, written the
// way an attacker would attack it: mint, then try every read path that could
// betray which token is the good one.
func TestPendingSaltHidesSeedTraitsAndArt(cur realm, t *testing.T) {
	c := newTestCollection(cur, "901", 0, 0)
	defer dropTestCollection("901")
	c.generative = true
	c.engine = Engine
	c.saltCommit = sha256Hex("my-secret-901")

	mintGenerativeOne(cur, testBuyer, "901")
	mintGenerativeOne(cur, testBuyer, "901")

	uassert.Equal(t, "pending", SeedSaltState("901"))
	uassert.True(t, revealPending(c))

	// The seed is the whole map: it must not be readable, by any route.
	uassert.Equal(t, "", TokenSeed("901", "1"))
	uassert.Equal(t, "", TokenSeed("901", "2"))
	uassert.Equal(t, "", seedOf(c, "1"))

	// Traits report an honest placeholder instead of real ones.
	attrs := TokenAttributes("901", "1")
	uassert.Equal(t, 1, len(attrs))
	uassert.Equal(t, "Status", attrs[0].TraitType)
	uassert.Equal(t, "Unrevealed", attrs[0].Value)

	// Every token renders the SAME placeholder, so rarity cannot be read
	// out of the artwork either.
	one, err := TokenURI("901", "1")
	uassert.NoError(t, err)
	two, err := TokenURI("901", "2")
	uassert.NoError(t, err)
	uassert.Equal(t, one, two)
	uassert.Equal(t, preRevealURI(c), one)
	uassert.True(t, strings.HasPrefix(one, "data:"))

	// Each mint fed the accumulator the creator could not predict.
	uassert.True(t, c.saltEntropy != 0)

	// And an unrevealed collection is not "verified" by omission.
	uassert.False(t, VerifySeedSalt("901"))

	// A never-minted token still reports nothing at all.
	uassert.Equal(t, "", TokenSeed("901", "3"))
	uassert.Equal(t, 0, len(TokenAttributes("901", "3")))
}

// TestRevealMakesArtSaltedAndVerifiable walks the full lifecycle and pins
// both gates: no reveal before the supply is gone, no reveal with a secret
// that does not match the commitment, and exactly one reveal ever.
func TestRevealMakesArtSaltedAndVerifiable(cur realm, t *testing.T) {
	c := newTestCollection(cur, "902", 0, 0)
	defer dropTestCollection("902")
	c.maxSupply = 2
	c.generative = true
	c.engine = Engine
	c.creator = callerOf(cur)
	secret := "reveal-me-902"
	c.saltCommit = sha256Hex(secret)

	mintGenerativeOne(cur, testBuyer, "902")

	// Revealing now would hand the creator the map of the token still
	// unminted, so the chain refuses rather than trusting restraint.
	uassert.PanicsContains(t, cur, "once the supply is minted out", func() {
		RevealSeedSalt(cur, "902", secret)
	})

	mintGenerativeOne(cur, testBuyer, "902")

	// Gate open, but the commitment still has to hold.
	uassert.PanicsContains(t, cur, "does not match", func() {
		RevealSeedSalt(cur, "902", "wrong-secret")
	})

	salt := RevealSeedSalt(cur, "902", secret)
	uassert.Equal(t, saltFrom(secret, c.saltEntropy, "902"), salt)
	uassert.Equal(t, "revealed", SeedSaltState("902"))
	uassert.True(t, VerifySeedSalt("902"))
	uassert.False(t, revealPending(c))

	// The art is now the salted art - and demonstrably NOT the unsalted
	// art anybody could have precomputed before the sale.
	uassert.Equal(t, nftgen1.SeedForSalted("902", "1", salt), TokenSeed("902", "1"))
	uassert.True(t, TokenSeed("902", "1") != "902:1")
	uassert.Equal(t, 10, len(TokenAttributes("902", "1")))

	uri, err := TokenURI("902", "1")
	uassert.NoError(t, err)
	uassert.Equal(t, nftgen1.DataURI(nftgen1.SeedForSalted("902", "1", salt)), uri)
	uassert.True(t, uri != preRevealURI(c))

	// Deterministic from here to forever, and the two tokens differ.
	again, err := TokenURI("902", "1")
	uassert.NoError(t, err)
	uassert.Equal(t, uri, again)
	other, err := TokenURI("902", "2")
	uassert.NoError(t, err)
	uassert.True(t, other != uri)

	// One-way latch: a second reveal cannot rewrite anybody's artwork.
	uassert.PanicsContains(t, cur, "already revealed", func() {
		RevealSeedSalt(cur, "902", secret)
	})
}

// TestVerifyCatchesATamperedReveal is the check a buyer actually runs. It
// must fail for a salt that does not follow from the published inputs, and
// for a secret that does not hash to the commitment - otherwise "verified"
// would mean nothing.
func TestVerifyCatchesATamperedReveal(cur realm, t *testing.T) {
	c := newTestCollection(cur, "903", 0, 0)
	defer dropTestCollection("903")
	c.generative = true
	c.engine = Engine
	c.saltCommit = sha256Hex("honest-903")
	c.saltSecret = "honest-903"
	c.saltEntropy = 77
	c.seedSalt = saltFrom("honest-903", 77, "903")
	c.saltRevealed = true
	uassert.True(t, verifySalt(c))

	// Salt that does not follow from (secret, entropy, id).
	c.seedSalt = saltFrom("honest-903", 78, "903")
	uassert.False(t, verifySalt(c))
	c.seedSalt = saltFrom("honest-903", 77, "903")
	uassert.True(t, verifySalt(c))

	// Secret swapped after the fact: the commitment no longer matches.
	c.saltSecret = "swapped"
	uassert.False(t, verifySalt(c))
}

// TestCommitGuards covers the input validation on the commitment, including
// the case-insensitivity that stops a creator from "failing" verification
// later purely because their tool emitted uppercase hex.
func TestCommitGuards(cur realm, t *testing.T) {
	c := newTestCollection(cur, "904", 0, 0)
	defer dropTestCollection("904")
	c.creator = callerOf(cur)

	uassert.PanicsContains(t, cur, "only apply to generative collections", func() {
		CommitSeedSalt(cur, "904", sha256Hex("s"))
	})

	c.generative = true
	c.engine = Engine

	uassert.PanicsContains(t, cur, "64-character hex", func() {
		CommitSeedSalt(cur, "904", "abc")
	})
	uassert.PanicsContains(t, cur, "valid hex", func() {
		CommitSeedSalt(cur, "904", strings.Repeat("z", 64))
	})

	CommitSeedSalt(cur, "904", strings.ToUpper(sha256Hex("s")))
	uassert.Equal(t, sha256Hex("s"), c.saltCommit)
	uassert.Equal(t, "pending", SeedSaltState("904"))

	uassert.PanicsContains(t, cur, "already has a seed salt commitment", func() {
		CommitSeedSalt(cur, "904", sha256Hex("t"))
	})
}

// TestCommitRefusedAfterFirstMint protects existing owners: a salt committed
// after a token exists would rewrite artwork somebody already bought.
func TestCommitRefusedAfterFirstMint(cur realm, t *testing.T) {
	c := newTestCollection(cur, "905", 0, 0)
	defer dropTestCollection("905")
	c.creator = callerOf(cur)
	c.generative = true
	c.engine = Engine

	mintGenerativeOne(cur, testBuyer, "905")

	uassert.PanicsContains(t, cur, "before the first mint", func() {
		CommitSeedSalt(cur, "905", sha256Hex("late"))
	})
}

// TestOnlyCreatorControlsTheSalt keeps both salt entry points creator-only,
// so a stranger can neither pre-empt a commitment nor force an early reveal
// of somebody else's drop.
func TestOnlyCreatorControlsTheSalt(cur realm, t *testing.T) {
	c := newTestCollection(cur, "906", 0, 0) // creator is testCreator
	defer dropTestCollection("906")
	c.generative = true
	c.engine = Engine
	c.saltCommit = sha256Hex("x")

	uassert.PanicsContains(t, cur, "only the collection's creator", func() {
		CommitSeedSalt(cur, "906", sha256Hex("y"))
	})
	uassert.PanicsContains(t, cur, "only the collection's creator", func() {
		RevealSeedSalt(cur, "906", "x")
	})
}

// TestSetGenerativeDropsAnUnusedCommitment covers the small housekeeping
// path: turning generative mode off before any mint must not leave a stale
// commitment that would silently apply to a later run.
func TestSetGenerativeDropsAnUnusedCommitment(cur realm, t *testing.T) {
	c := newTestCollection(cur, "907", 0, 0)
	defer dropTestCollection("907")
	c.creator = callerOf(cur)
	c.generative = true
	c.engine = Engine
	c.saltCommit = sha256Hex("stale")
	c.saltEntropy = 5

	SetGenerative(cur, "907", false)
	uassert.Equal(t, "", c.saltCommit)
	uassert.Equal(t, int64(0), c.saltEntropy)
	uassert.Equal(t, "", c.engine)
	uassert.Equal(t, "none", SeedSaltState("907"))

	SetGenerative(cur, "907", true)
	uassert.Equal(t, Engine, c.engine)
	uassert.True(t, strings.HasSuffix(c.engine, "/nftgen1"))
}

package nft57

import (
	"strings"
	"testing"

	"gno.land/p/nt/uassert/v0"
)

// These tests are written from the attacker's side: each one is an attempt
// to put something on chain that a client would later execute or
// mis-parse. A realm cannot assume every wallet, explorer and frontend
// sanitises what it reads, so the refusal has to happen at write time -
// once minted, a tokenURI is permanent.

// TestSafeURIAcceptsRenderableSchemes pins the schemes a legitimate mint
// still needs, so the hardening cannot silently break normal minting.
func TestSafeURIAcceptsRenderableSchemes(cur realm, t *testing.T) {
	for _, good := range []string{
		"", // no URI: inherits the collection baseURI
		"https://cdn.example.com/1.png",
		"ipfs://bafybeigdyrzt5example/1.json",
		"ar://abc123",
		"data:image/svg+xml;base64,PHN2Zz48L3N2Zz4=",
		"data:application/json;base64,e30=",
	} {
		uri := good
		uassert.NotPanics(t, cur, func() { assertSafeURI(uri, "tokenURI") })
	}
}

// TestSafeURIRejectsExecutablePayloads is the actual attack: mint into a
// public collection with a script payload as the artwork URI and wait for
// a client to render it. Stored XSS on an immutable record.
func TestSafeURIRejectsExecutablePayloads(cur realm, t *testing.T) {
	for _, bad := range []string{
		"javascript:alert(document.cookie)",
		"JaVaScRiPt:alert(1)",
		"vbscript:msgbox(1)",
		"data:text/html;base64,PHNjcmlwdD5hbGVydCgxKTwvc2NyaXB0Pg==",
		"data:text/javascript,alert(1)",
		"file:///etc/passwd",
	} {
		uri := bad
		uassert.PanicsContains(t, cur, "must start with https://", func() {
			assertSafeURI(uri, "tokenURI")
		})
	}
}

// TestMetadataEscapesControlCharacters covers the second half of the same
// idea: a collection name carrying a quote, a backslash or a raw control
// byte must not be able to break out of the JSON document the realm
// serves as token metadata.
func TestMetadataEscapesControlCharacters(t *testing.T) {
	escaped := jsonEscape("a\"b\\c\nd\x01e")
	uassert.Equal(t, `a\"b\\c\nd\u0001e`, escaped)

	// No raw control byte survives the escape.
	for i := 0; i < 0x20; i++ {
		out := jsonEscape(string(rune(i)))
		uassert.False(t, strings.ContainsRune(out, rune(i)))
	}
}

// TestRoyaltyCannotExceedSalePrice keeps the marketplace payout split
// solvent: the royalty is derived from an immutable collection field that
// CreateCollection bounds, so no sale can ever owe more than it took in.
func TestRoyaltyCannotExceedSalePrice(t *testing.T) {
	uassert.True(t, MaxRoyaltyPercent <= 100)
	for _, price := range []int64{1, 1_000_000, 1_000_000_000} {
		royalty := price * int64(MaxRoyaltyPercent) / 100
		uassert.True(t, royalty <= price)
		uassert.True(t, royalty >= 0)
	}
}

package nft57

import (
	"strconv"
	"strings"
	"testing"

	"gno.land/p/nt/uassert/v0"
)

// These tests pin the v5.7 changes. The rule is the same one the earlier
// cost work followed: a cheaper or more flexible path is only acceptable if
// nothing a buyer reads becomes less trustworthy. So each test here checks
// both halves - the new capability works, AND the guarantee it could have
// weakened still holds.

// TestBaseURIFallbackResolvesTokens covers v5.7 change 1: an IPFS-style
// collection writes ONE baseURI and every token derives its URI from it.
// This is what makes a 1000-piece collection cost one write instead of
// one transaction per token.
func TestBaseURIFallbackResolvesTokens(cur realm, t *testing.T) {
	c := newTestCollection(cur, "600", 0, 0)
	defer dropTestCollection("600")
	c.baseURI = "ipfs://QmFolderCID/"

	// Three tokens, no per-token URI stored anywhere.
	mint(cur, testBuyer, "600", "", "")
	mint(cur, testBuyer, "600", "", "")
	mint(cur, testBuyer, "600", "", "")

	for i := 1; i <= 3; i++ {
		id := strconv.Itoa(i)
		uri, err := TokenURI("600", id)
		uassert.NoError(t, err)
		uassert.Equal(t, "ipfs://QmFolderCID/"+id, uri)
	}

	// A token that was never minted must NOT resolve to a plausible-looking
	// baseURI: the existence gate runs first.
	_, err := TokenURI("600", "4")
	uassert.Error(t, err)
}

// TestStoredTokenURIWinsOverBaseURI keeps the resolution order honest: a
// token that carries its own URI must never be overridden by a
// collection-level default.
func TestStoredTokenURIWinsOverBaseURI(cur realm, t *testing.T) {
	c := newTestCollection(cur, "601", 0, 0)
	defer dropTestCollection("601")
	c.baseURI = "ipfs://QmFolderCID/"

	mint(cur, testBuyer, "601", "ipfs://QmSpecificToken", "")

	uri, err := TokenURI("601", "1")
	uassert.NoError(t, err)
	uassert.Equal(t, "ipfs://QmSpecificToken", uri)
}

// TestGenerativeBeatsBaseURI proves a generative collection is never
// diverted to off-chain art even if a baseURI happens to be set: on-chain
// provenance outranks a collection-level default.
func TestGenerativeBeatsBaseURI(cur realm, t *testing.T) {
	c := newTestCollection(cur, "602", 0, 0)
	defer dropTestCollection("602")
	c.baseURI = "ipfs://QmFolderCID/"
	c.generative = true
	c.engine = Engine

	mintGenerativeOne(cur, testBuyer, "602")

	uri, err := TokenURI("602", "1")
	uassert.NoError(t, err)
	uassert.True(t, strings.HasPrefix(uri, "data:"))
}

// TestBaseURIIsOneShot is the security half of the reveal feature (v5.7
// change 2). The creator may reveal exactly once; the second attempt is
// refused forever, so a buyer's artwork cannot be rewritten after purchase
// the way it can on an Ethereum contract with a permanently callable
// setBaseURI.
func TestBaseURIIsOneShot(cur realm, t *testing.T) {
	c := newTestCollection(cur, "603", 0, 0)
	defer dropTestCollection("603")
	c.baseURI = "ipfs://QmPlaceholder/"
	c.creator = callerOf(cur)

	uassert.False(t, c.baseURILocked)

	SetBaseURI(cur, "603", "ipfs://QmRealCID/")
	uassert.Equal(t, "ipfs://QmRealCID/", c.baseURI)
	uassert.True(t, c.baseURILocked)

	uassert.PanicsWithMessage(t, cur,
		"this collection's baseURI is locked and can never be changed again",
		func() { SetBaseURI(cur, "603", "ipfs://QmAttackerCID/") })

	// The locked value survived the refused call.
	uassert.Equal(t, "ipfs://QmRealCID/", c.baseURI)
}

// TestLockBaseURIWithoutReveal covers the creator who needs no reveal and
// wants to prove immutability up front.
func TestLockBaseURIWithoutReveal(cur realm, t *testing.T) {
	c := newTestCollection(cur, "604", 0, 0)
	defer dropTestCollection("604")
	c.baseURI = "ipfs://QmFinalCID/"
	c.creator = callerOf(cur)

	LockBaseURI(cur, "604")
	uassert.True(t, c.baseURILocked)
	uassert.Equal(t, "ipfs://QmFinalCID/", c.baseURI)

	uassert.PanicsWithMessage(t, cur,
		"this collection's baseURI is already locked",
		func() { LockBaseURI(cur, "604") })

	uassert.PanicsWithMessage(t, cur,
		"this collection's baseURI is locked and can never be changed again",
		func() { SetBaseURI(cur, "604", "ipfs://QmSomethingElse/") })
}

// TestSetBaseURIRejectsUnsafeSchemes makes sure the reveal path did not open
// a hole around the v5.5 URI validation: an immutable javascript: or
// data:text/html payload would be stored XSS living on chain forever.
func TestSetBaseURIRejectsUnsafeSchemes(cur realm, t *testing.T) {
	c := newTestCollection(cur, "605", 0, 0)
	defer dropTestCollection("605")
	c.creator = callerOf(cur)

	uassert.PanicsWithMessage(t, cur,
		"baseURI must start with https://, ipfs://, ar://, data:image/ or data:application/json",
		func() { SetBaseURI(cur, "605", "javascript:alert(1)") })

	// A refused reveal must not consume the one-shot right.
	uassert.False(t, c.baseURILocked)
}

// TestMintBatchMintsManyInOneCall covers v5.7 change 5.
func TestMintBatchMintsManyInOneCall(cur realm, t *testing.T) {
	c := newTestCollection(cur, "606", 0, 0)
	defer dropTestCollection("606")
	c.baseURI = "ipfs://QmFolderCID/"

	ids := mintBatch(cur, testBuyer, "606", 5)
	uassert.Equal(t, "1,2,3,4,5", ids)
	uassert.Equal(t, int64(5), c.mintedTotal)
	uassert.Equal(t, int64(6), c.nextTokenID)

	// Every batched token resolves exactly like a singly minted one.
	uri, err := TokenURI("606", "5")
	uassert.NoError(t, err)
	uassert.Equal(t, "ipfs://QmFolderCID/5", uri)
}

// TestMintBatchGenerative proves a batch of generative mints is identical to
// the same mints done one at a time - same seeds, same traits, nothing
// stored.
func TestMintBatchGenerative(cur realm, t *testing.T) {
	c := newTestCollection(cur, "607", 0, 0)
	defer dropTestCollection("607")
	c.generative = true
	c.engine = Engine

	mintBatch(cur, testBuyer, "607", 3)
	uassert.Equal(t, int64(3), c.mintedTotal)
	uassert.Equal(t, int64(3), c.onchainTokens)

	for i := 1; i <= 3; i++ {
		id := strconv.Itoa(i)
		uassert.Equal(t, "607:"+id, TokenSeed("607", id))
		uassert.Equal(t, 10, len(TokenAttributes("607", id)))
		uassert.Equal(t, nil, avlGet(attributes, "607:"+id))
	}
}

// TestMintBatchRespectsEveryLimit is the important half: batching must not
// become a way around the checks a single mint has to pass.
func TestMintBatchRespectsEveryLimit(cur realm, t *testing.T) {
	// Per-wallet cap still bites mid-batch.
	capped := newTestCollection(cur, "608", 0, 2)
	defer dropTestCollection("608")
	uassert.PanicsWithMessage(t, cur,
		"wallet has reached this collection's per-wallet mint limit of 2",
		func() { mintBatch(cur, testBuyer, "608", 3) })
	_ = capped

	// Max supply still bites mid-batch.
	small := newTestCollection(cur, "609", 0, 0)
	defer dropTestCollection("609")
	small.maxSupply = 2
	uassert.PanicsWithMessage(t, cur,
		"collection has reached its max supply",
		func() { mintBatch(cur, testBuyer, "609", 4) })

	// And the batch size itself is bounded.
	big := newTestCollection(cur, "610", 0, 0)
	defer dropTestCollection("610")
	uassert.PanicsWithMessage(t, cur,
		"count must be at most 25 per call",
		func() { mintBatch(cur, testBuyer, "610", MaxMintBatch+1) })
	uassert.PanicsWithMessage(t, cur,
		"count must be positive",
		func() { mintBatch(cur, testBuyer, "610", 0) })
	uassert.Equal(t, int64(0), big.mintedTotal)
}

// TestCollectionURIRoundTrips covers v5.7 change 4, including the fact that
// it is validated like every other URI this realm persists.
func TestCollectionURIRoundTrips(cur realm, t *testing.T) {
	c := newTestCollection(cur, "611", 0, 0)
	defer dropTestCollection("611")
	c.creator = callerOf(cur)

	SetCollectionURI(cur, "611", "ipfs://QmCollectionMeta")
	uassert.Equal(t, "ipfs://QmCollectionMeta", GetCollection("611").CollectionURI)

	uassert.PanicsWithMessage(t, cur,
		"uri must start with https://, ipfs://, ar://, data:image/ or data:application/json",
		func() { SetCollectionURI(cur, "611", "data:text/html,<script>") })
}

// TestCollectionInfoExposesLockState makes sure the UI can badge a
// collection honestly: "can this art still change?" must be answerable from
// a plain read.
func TestCollectionInfoExposesLockState(cur realm, t *testing.T) {
	c := newTestCollection(cur, "612", 0, 0)
	defer dropTestCollection("612")
	c.baseURI = "ipfs://QmFolderCID/"
	c.creator = callerOf(cur)

	uassert.False(t, GetCollection("612").BaseURILocked)
	LockBaseURI(cur, "612")
	uassert.True(t, GetCollection("612").BaseURILocked)
}

package nftmarket57

import "gno.land/p/nt/avl/v0"

// avlGet is the ONE place where this package touches avl.Tree.Get.
//
// The avl/v0 published on gno.land returns (value, exists); the one
// shipped with the pearl testnet's GNOROOT returns a single value. Every
// other line of this package is identical on both networks, so the whole
// difference is isolated here instead of being spread over every call
// site. Switch it with: python3 scripts/avl-shim.py <pearl|mainnet>
//
// AVL-VARIANT: pearl
func avlGet(t *avl.Tree, key string) any {
	return t.Get(key)
}

package nftmarket57

import (
	"strconv"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

// v5.7 replaced three duplicated index trees with filtered walks over the
// one active-only index. That is a fee win, but it is only acceptable if
// every read still returns EXACTLY what it returned before. These tests pin
// the answers, including the two cases a prefix/filter rewrite is most
// likely to get wrong: collection 1 leaking collection 11's listings, and
// paging a filtered view skipping rows.

func addTestListing(id, cid, tid int64, seller address, price int64) *Listing {
	l := &Listing{id: id, collectionID: cid, tokenID: tid, seller: seller, priceUgnot: price, active: true}
	listings.Set(padID(l.id), l)
	byToken.Set(strconv.FormatInt(cid, 10)+":"+strconv.FormatInt(tid, 10), l.id)
	indexActive(l)
	return l
}

func dropTestListing(l *Listing) {
	if l.active {
		deactivate(l)
	}
	listings.Remove(padID(l.id))
}

// TestListByCollectionDoesNotLeakNeighbours is the prefix test. byToken is
// keyed "collectionId:tokenId", so collection "1" must match "1:*" and never
// "11:*" - a naive prefix range would hand a buyer the wrong collection's
// floor price.
func TestListByCollectionDoesNotLeakNeighbours(t *testing.T) {
	seller := testutils.TestAddress("c1seller")
	one := addTestListing(101, 1, 1, seller, 5_000_000)
	defer dropTestListing(one)
	oneAgain := addTestListing(102, 1, 2, seller, 3_000_000)
	defer dropTestListing(oneAgain)
	eleven := addTestListing(103, 11, 1, seller, 1_000_000)
	defer dropTestListing(eleven)

	gotOne := ListByCollection("1", 0, 10)
	uassert.Equal(t, 2, len(gotOne))
	for _, li := range gotOne {
		uassert.Equal(t, "1", li.CollectionID)
	}

	gotEleven := ListByCollection("11", 0, 10)
	uassert.Equal(t, 1, len(gotEleven))
	uassert.Equal(t, "11", gotEleven[0].CollectionID)

	// The floor must be the collection's own cheapest listing, not the
	// cheapest listing on the whole marketplace.
	uassert.Equal(t, int64(3_000_000), FloorPrice("1"))
	uassert.Equal(t, int64(1_000_000), FloorPrice("11"))
	uassert.Equal(t, int64(0), FloorPrice("7"))
}

// TestListBySellerFiltersAcrossCollections covers the read that lost its
// dedicated tree: a seller's page must gather their listings from every
// collection and include nobody else's.
func TestListBySellerFiltersAcrossCollections(t *testing.T) {
	me := testutils.TestAddress("mine")
	other := testutils.TestAddress("theirs")

	a := addTestListing(111, 1, 5, me, 1_000)
	defer dropTestListing(a)
	b := addTestListing(112, 2, 5, me, 2_000)
	defer dropTestListing(b)
	c := addTestListing(113, 3, 5, me, 3_000)
	defer dropTestListing(c)
	d := addTestListing(114, 2, 6, other, 9_000)
	defer dropTestListing(d)

	mine := ListBySeller(me, 0, 10)
	uassert.Equal(t, 3, len(mine))
	for _, li := range mine {
		uassert.Equal(t, me, li.Seller)
	}
	uassert.Equal(t, 1, len(ListBySeller(other, 0, 10)))
	uassert.Equal(t, 0, len(ListBySeller(testutils.TestAddress("nobody"), 0, 10)))
}

// TestFilteredPagingCoversEveryRow is the subtle one: offset now counts
// MATCHED rows, so walking a filtered view page by page must visit each
// listing exactly once - no skips, no repeats.
func TestFilteredPagingCoversEveryRow(t *testing.T) {
	me := testutils.TestAddress("pager")
	noise := testutils.TestAddress("noise")

	// Interleave another seller's listings so a buggy offset would drift.
	a := addTestListing(121, 1, 21, me, 1_000)
	defer dropTestListing(a)
	n1 := addTestListing(122, 1, 22, noise, 1_000)
	defer dropTestListing(n1)
	b := addTestListing(123, 1, 23, me, 2_000)
	defer dropTestListing(b)
	n2 := addTestListing(124, 1, 24, noise, 1_000)
	defer dropTestListing(n2)
	c := addTestListing(125, 1, 25, me, 3_000)
	defer dropTestListing(c)

	first := ListBySeller(me, 0, 2)
	second := ListBySeller(me, 2, 2)
	uassert.Equal(t, 2, len(first))
	uassert.Equal(t, 1, len(second))

	seen := map[string]bool{}
	for _, li := range first {
		seen[li.ID] = true
	}
	for _, li := range second {
		uassert.False(t, seen[li.ID]) // no repeats across pages
		seen[li.ID] = true
	}
	uassert.Equal(t, 3, len(seen))
	uassert.True(t, seen["121"])
	uassert.True(t, seen["123"])
	uassert.True(t, seen["125"])

	// Paging past the end is empty, not a panic or a wrapped page.
	uassert.Equal(t, 0, len(ListBySeller(me, 3, 2)))
	// limit 0 means "no limit", as before.
	uassert.Equal(t, 3, len(ListBySeller(me, 0, 0)))
}

// TestClosingAListingRemovesItFromEveryRead is the safety half: with one
// index, a single removal has to take the listing out of all four reads at
// once. If it did not, the marketplace could sell a token twice.
func TestClosingAListingRemovesItFromEveryRead(t *testing.T) {
	seller := testutils.TestAddress("closer")
	l := addTestListing(131, 4, 9, seller, 7_000)
	defer dropTestListing(l)

	uassert.Equal(t, "131", ListingForToken("4", "9").ID)
	uassert.Equal(t, 1, len(ListActive(0, 10)))
	uassert.Equal(t, 1, len(ListBySeller(seller, 0, 10)))
	uassert.Equal(t, 1, len(ListByCollection("4", 0, 10)))
	uassert.Equal(t, int64(7_000), FloorPrice("4"))

	deactivate(l)

	uassert.Equal(t, "", ListingForToken("4", "9").ID)
	uassert.Equal(t, 0, len(ListActive(0, 10)))
	uassert.Equal(t, 0, len(ListBySeller(seller, 0, 10)))
	uassert.Equal(t, 0, len(ListByCollection("4", 0, 10)))
	uassert.Equal(t, int64(0), FloorPrice("4"))

	// The record itself survives for history/receipts, just not as active.
	uassert.Equal(t, "131", GetListing("131").ID)
	uassert.False(t, GetListing("131").Active)

	// And the token is free to be listed again: the guard entry is gone.
	uassert.Equal(t, nil, avlGet(byToken, "4:9"))
}

// Package nftmarket57 is the v5 non-custodial GNOT marketplace for
// collections minted through gno.land/r/g1hx4z2.../nft57.
//
// Behaviour is identical to nftmarket4 (same functions, same events, same
// non-custodial approval model). What changed is what a sale record costs
// to keep on chain.
//
// WHAT CHANGED VS V4 (gno.land/r/g1hx4z2.../nftmarket4)
//
//  1. Records are roughly half the size. v4 stored every numeric field as
//     a string ("1", "12", "5000000") inside the Listing itself AND wrote
//     the listing ID as a string into four index trees. Measured on
//     pearl-1, one listing wrote about 8 KB, i.e. ~0.8 GNOT of storage
//     deposit per List call. v5 keeps ids, collection ids, token ids and
//     prices as int64 internally and stores int64 values in the indexes,
//     so the same listing costs materially less to open. The exported
//     ListingInfo still speaks strings, so the frontend decoder is
//     unchanged - only the pkgpath in config/gno.ts moves.
//
//  2. It points at nft57, whose generative tokens render from a seed.
//     Nothing here has to know that: TokenURI resolution happens inside
//     nft57.
//
//  3. ONE index instead of four. v5.5 wrote listings + byToken +
//     activeIndex + bySeller + byCollection on every List - five AVL
//     nodes - and removed four of them on every Cancel/Buy. The last
//     three held nothing that byToken did not already reach, and byToken
//     is active-only (deactivate removes it), so seller/collection/active
//     pagination is now a filtered walk over byToken instead of three
//     duplicated trees. Listing a token costs two writes, not five.
//
//     This is deliberately NOT a move to an off-chain indexer: every
//     query still answers from chain state, so the marketplace keeps
//     working if the indexer is down. The price paid is that
//     ListBySeller scans the active book (bounded by the number of live
//     listings, not by history) and results are ordered by
//     collection:token rather than by listing id.
//
// Everything v4 already got right is kept deliberately: authorization via
// cur.Previous().Address(), assertDirectPayment on the one function that
// takes money, deactivate-before-payout ordering, and real active-only
// pagination indexes.
package nftmarket57

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/nt/avl/v0"
	"gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nft57"
)

// Listing is one active or historical sale offer. Every numeric field is
// an int64 on purpose - see the package doc, change #1.
type Listing struct {
	id           int64
	collectionID int64
	tokenID      int64
	seller       address
	priceUgnot   int64
	active       bool
	createdAt    int64
}

// ListingInfo is the exported, read-only view of a Listing. IDs stay
// strings here so existing frontend decoders keep working untouched.
type ListingInfo struct {
	ID           string
	CollectionID string
	TokenID      string
	Seller       address
	PriceUgnot   int64
	Active       bool
	CreatedAt    int64
}

var (
	listings = avl.NewTree() // paddedListingID -> *Listing (active and closed)
	// byToken is the ONLY live index: "collectionId:tokenId" -> int64
	// listing id, holding active listings exclusively (deactivate removes
	// the entry). It is simultaneously the duplicate-listing guard, the
	// per-token lookup, and the universe every paginated read walks.
	byToken     = avl.NewTree()
	nextID      int64
	activeCount int64
)

// assertDirectPayment rejects any call path where the tx's coin envelope
// cannot be trusted to have actually landed in this realm.
//
// IsUserCall() is true only when the previous frame is an EOA calling this
// function directly ("gnokey maketx call" / a wallet): its pkgPath is empty.
// Every code realm has a non-empty pkgPath, and MsgRun executes inside the
// ephemeral /e/<addr>/run realm, so both paths are rejected here.
//
// runtime.AssertOriginCall() is deliberately NOT used. Under the crossing
// model a "cur realm" function is always entered one frame below the message
// call itself, so the assert can never pass - not even for a legitimate
// direct wallet call. Verified on pearl-1: it aborted a real Buy tx with
// "invalid non-origin call".
func assertDirectPayment(cur realm) {
	if !cur.Previous().IsUserCall() {
		panic("this function must be called directly by a wallet, not through another realm")
	}
}

// List offers a token for sale at priceUgnot (1 GNOT = 1_000_000 ugnot).
// The caller must own the token and must have approved this realm's
// address on nft57 beforehand.
func List(cur realm, collectionID, tokenID string, priceUgnot int64) string {
	caller := cur.Previous().Address()
	if priceUgnot <= 0 {
		panic("price must be positive")
	}
	cid := parseID(collectionID, "collection id")
	tid := parseID(tokenID, "token id")

	owner, err := nft57.OwnerOf(collectionID, tokenID)
	if err != nil {
		panic(err)
	}
	if owner != caller {
		panic("only the token owner can list it")
	}
	assertApproved(cur, collectionID, tokenID, owner)

	key := collectionID + ":" + tokenID
	if listingID, ok := avlGet(byToken, key).(int64); ok {
		if l := getListing(listingID); l != nil && l.active {
			panic("token is already listed (listing #" + strconv.FormatInt(listingID, 10) + ")")
		}
	}

	nextID++
	l := &Listing{
		id:           nextID,
		collectionID: cid,
		tokenID:      tid,
		seller:       caller,
		priceUgnot:   priceUgnot,
		active:       true,
		createdAt:    runtime.ChainHeight(),
	}
	listings.Set(padID(l.id), l)
	byToken.Set(key, l.id)
	indexActive(l)

	id := strconv.FormatInt(l.id, 10)
	chain.Emit(
		"NFTListed",
		"listingId", id,
		"collection", collectionID,
		"tokenId", tokenID,
		"seller", caller.String(),
		"price", strconv.FormatInt(priceUgnot, 10),
	)

	return id
}

// UpdatePrice re-prices an active listing in place. Seller only.
func UpdatePrice(cur realm, listingID string, priceUgnot int64) {
	caller := cur.Previous().Address()
	l := mustGetListing(listingID)
	if !l.active {
		panic("listing is not active")
	}
	if l.seller != caller {
		panic("only the seller can change this listing's price")
	}
	if priceUgnot <= 0 {
		panic("price must be positive")
	}
	old := l.priceUgnot
	l.priceUgnot = priceUgnot

	chain.Emit(
		"NFTListingRepriced",
		"listingId", listingID,
		"oldPrice", strconv.FormatInt(old, 10),
		"price", strconv.FormatInt(priceUgnot, 10),
	)
}

// Cancel withdraws an active listing. Seller only.
func Cancel(cur realm, listingID string) {
	caller := cur.Previous().Address()
	l := mustGetListing(listingID)
	if !l.active {
		panic("listing is not active")
	}
	if l.seller != caller {
		panic("only the seller can cancel this listing")
	}

	deactivate(l)
	chain.Emit("NFTListingCancelled", "listingId", listingID)
}

// Buy purchases an active listing. The transaction must send at least the
// listing's priceUgnot; any excess is refunded. Royalties declared on the
// token are paid to the collection creator before the seller is paid.
func Buy(cur realm, listingID string) {
	assertDirectPayment(cur)
	caller := cur.Previous().Address()

	l := mustGetListing(listingID)
	if !l.active {
		panic("listing is not active")
	}
	if l.seller == caller {
		panic("cannot buy your own listing")
	}

	sentAmt := unsafe.OriginSend().AmountOf("ugnot")
	if sentAmt < l.priceUgnot {
		panic("insufficient payment: sent " + strconv.FormatInt(sentAmt, 10) +
			"ugnot, need " + strconv.FormatInt(l.priceUgnot, 10) + "ugnot")
	}

	collectionID := strconv.FormatInt(l.collectionID, 10)
	tokenID := strconv.FormatInt(l.tokenID, 10)

	// Deactivate first, then move money.
	deactivate(l)

	royaltyAddr, rawRoyalty, err := nft57.RoyaltyInfo(collectionID, tokenID, l.priceUgnot)
	if err != nil {
		rawRoyalty = 0
	}
	royaltyAmt, sellerAmt, refund := splitPayment(l.priceUgnot, sentAmt, rawRoyalty, royaltyAddr == l.seller)

	marketAddr := cur.Address()
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	if royaltyAmt > 0 {
		bk.SendCoins(marketAddr, royaltyAddr, chain.NewCoins(chain.NewCoin("ugnot", royaltyAmt)))
	}
	bk.SendCoins(marketAddr, l.seller, chain.NewCoins(chain.NewCoin("ugnot", sellerAmt)))
	if refund > 0 {
		bk.SendCoins(marketAddr, caller, chain.NewCoins(chain.NewCoin("ugnot", refund)))
	}

	// Cross into nft57 to move ownership. This reverts the whole tx,
	// including the transfers above, if the seller's approval no longer
	// stands or they no longer own the token.
	nft57.TransferFrom(cross(cur), collectionID, tokenID, l.seller, caller)

	chain.Emit(
		"NFTSold",
		"listingId", listingID,
		"collection", collectionID,
		"tokenId", tokenID,
		"seller", l.seller.String(),
		"buyer", caller.String(),
		"price", strconv.FormatInt(l.priceUgnot, 10),
		"royalty", strconv.FormatInt(royaltyAmt, 10),
	)
}

// splitPayment is the pure payout arithmetic, kept separate so it can be
// unit-tested without a funded chain: a royalty is only honoured when it
// is positive, strictly smaller than the price, and not payable to the
// seller themselves (in which case paying it would just be a needless
// extra transfer of the seller's own money).
func splitPayment(price, sent, royalty int64, royaltyGoesToSeller bool) (royaltyAmt, sellerAmt, refund int64) {
	if royalty <= 0 || royalty >= price || royaltyGoesToSeller {
		royalty = 0
	}
	refund = sent - price
	if refund < 0 {
		refund = 0
	}
	return royalty, price - royalty, refund
}

// Read-only views.

// GetListing returns one listing by ID.
func GetListing(listingID string) ListingInfo {
	return toInfo(mustGetListing(listingID))
}

// ListActive returns exactly one page of ACTIVE listings, ordered by
// collection then token (v5.7: see the package doc, change #3 - v5.5
// ordered by listing id).
func ListActive(offset, limit int64) []ListingInfo {
	return pageActive("", "", nil, offset, limit)
}

// ListBySeller returns a page of one seller's active listings. This walks
// the active book and filters, so its cost tracks the number of LIVE
// listings rather than the number of listings ever created.
func ListBySeller(seller address, offset, limit int64) []ListingInfo {
	return pageActive("", "", func(l *Listing) bool { return l.seller == seller }, offset, limit)
}

// ListByCollection returns a page of one collection's active listings.
// byToken is keyed "collectionId:tokenId", so this is a true prefix range:
// collection 1 cannot leak listings from collection 11.
func ListByCollection(collectionID string, offset, limit int64) []ListingInfo {
	return pageActive(collectionID+":", collectionID+";", nil, offset, limit)
}

// ListingForToken returns the active listing on a token, or an empty
// ListingInfo if there is none - one lookup instead of scanning pages.
func ListingForToken(collectionID, tokenID string) ListingInfo {
	if id, ok := avlGet(byToken, collectionID+":"+tokenID).(int64); ok {
		if l := getListing(id); l != nil && l.active {
			return toInfo(l)
		}
	}
	return ListingInfo{}
}

// ListingCount returns the total number of listings ever created.
func ListingCount() int64 { return nextID }

// ActiveListingCount returns how many listings are currently active, so a
// UI can page without over-fetching.
func ActiveListingCount() int64 { return activeCount }

// FloorPrice returns the lowest active asking price across a collection
// (0 when it has no active listings).
func FloorPrice(collectionID string) int64 {
	var floor int64
	byToken.Iterate(collectionID+":", collectionID+";", func(key string, value any) bool {
		if l := getListing(value.(int64)); l != nil && l.active {
			if floor == 0 || l.priceUgnot < floor {
				floor = l.priceUgnot
			}
		}
		return false
	})
	return floor
}

// Render implements the gno.land realm home-page convention.
func Render(path string) string {
	if path != "" {
		l := getListingByString(path)
		if l == nil {
			return "# 404\n\nlisting not found: " + path
		}
		return renderListing(l)
	}

	out := "# gnoNFT Marketplace v5\n\n"
	if activeCount == 0 {
		return out + "No active listings.\n"
	}
	out += strconv.FormatInt(activeCount, 10) + " active listing(s)\n\n"
	byToken.Iterate("", "", func(key string, value any) bool {
		if l := getListing(value.(int64)); l != nil {
			out += renderListing(l) + "\n"
		}
		return false
	})
	return out
}

func renderListing(l *Listing) string {
	status := "active"
	if !l.active {
		status = "sold/cancelled"
	}
	return "- #" + strconv.FormatInt(l.id, 10) + " " +
		strconv.FormatInt(l.collectionID, 10) + ":" + strconv.FormatInt(l.tokenID, 10) +
		" - " + strconv.FormatInt(l.priceUgnot, 10) + "ugnot - seller " + l.seller.String() +
		" (" + status + ")"
}

// Internal helpers.

func assertApproved(cur realm, collectionID, tokenID string, owner address) {
	marketAddr := cur.Address()
	approved, _ := nft57.GetApproved(collectionID, tokenID)
	if approved != marketAddr && !nft57.IsApprovedForAll(collectionID, owner, marketAddr) {
		panic("marketplace is not approved to transfer this token yet; call nft57.Approve or nft57.SetApprovalForAll first")
	}
}

// indexActive records that a listing is live. The byToken entry is written
// by List itself (it doubles as the already-listed guard), so all that is
// left here is the counter - which is a plain int64 field, not an AVL node.
func indexActive(l *Listing) {
	activeCount++
}

func deactivate(l *Listing) {
	l.active = false
	// Dropping the byToken entry is what frees the token to be relisted and
	// what removes the listing from every paginated read at once.
	byToken.Remove(strconv.FormatInt(l.collectionID, 10) + ":" + strconv.FormatInt(l.tokenID, 10))
	if activeCount > 0 {
		activeCount--
	}
}

// pageActive walks the active book (byToken) over an optional key range,
// applies an optional predicate, and returns one page. Offset counts only
// rows that actually matched, so paging through a filtered view can never
// skip results the way offsetting over a pre-filtered tree could.
func pageActive(start, end string, keep func(*Listing) bool, offset, limit int64) []ListingInfo {
	if offset < 0 {
		offset = 0
	}
	if limit < 0 {
		limit = 0
	}
	out := make([]ListingInfo, 0, limit)
	var seen int64
	byToken.Iterate(start, end, func(key string, value any) bool {
		l := getListing(value.(int64))
		if l == nil || !l.active {
			return false
		}
		if keep != nil && !keep(l) {
			return false
		}
		if seen < offset {
			seen++
			return false
		}
		if limit > 0 && int64(len(out)) >= limit {
			return true
		}
		out = append(out, toInfo(l))
		seen++
		return false
	})
	return out
}

// padID zero-pads a numeric ID so index trees sort numerically rather
// than lexicographically ("10" must come after "2").
func padID(id int64) string {
	const width = 12
	s := strconv.FormatInt(id, 10)
	if len(s) >= width {
		return s
	}
	return "000000000000"[:width-len(s)] + s
}

// parseID rejects anything that is not a positive decimal integer, so a
// malformed id can never be written into a record or an index key.
func parseID(s, what string) int64 {
	v, err := strconv.ParseInt(s, 10, 64)
	if err != nil || v <= 0 {
		panic("invalid " + what + ": " + s)
	}
	return v
}

func toInfo(l *Listing) ListingInfo {
	return ListingInfo{
		ID:           strconv.FormatInt(l.id, 10),
		CollectionID: strconv.FormatInt(l.collectionID, 10),
		TokenID:      strconv.FormatInt(l.tokenID, 10),
		Seller:       l.seller,
		PriceUgnot:   l.priceUgnot,
		Active:       l.active,
		CreatedAt:    l.createdAt,
	}
}

func getListing(id int64) *Listing {
	v := avlGet(listings, padID(id))
	if v == nil {
		return nil
	}
	return v.(*Listing)
}

func getListingByString(id string) *Listing {
	v, err := strconv.ParseInt(id, 10, 64)
	if err != nil {
		return nil
	}
	return getListing(v)
}

func mustGetListing(id string) *Listing {
	l := getListingByString(id)
	if l == nil {
		panic("listing not found: " + id)
	}
	return l
}

package nftmarket57

import (
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

// NOTE: List/Buy/Cancel need a funded chain and a direct wallet MsgCall, so
// those paths are verified on-chain on Pearl. The pure logic that v5 changed
// (int64 records, index keys, the exported string wire format) is tested here.

func TestSplitPayment(t *testing.T) {
	// Exact payment, royalty to a third party.
	royalty, seller, refund := splitPayment(1000, 1000, 50, false)
	uassert.Equal(t, int64(50), royalty)
	uassert.Equal(t, int64(950), seller)
	uassert.Equal(t, int64(0), refund)

	// Overpayment is refunded, never kept by the realm.
	royalty, seller, refund = splitPayment(1000, 1500, 50, false)
	uassert.Equal(t, int64(500), refund)
	uassert.Equal(t, int64(1000), royalty+seller)

	// No royalty when it would just pay the seller their own money.
	royalty, seller, refund = splitPayment(1000, 1000, 50, true)
	uassert.Equal(t, int64(0), royalty)
	uassert.Equal(t, int64(1000), seller)

	// A royalty at or above the price is ignored rather than zeroing the seller.
	royalty, seller, _ = splitPayment(1000, 1000, 1000, false)
	uassert.Equal(t, int64(0), royalty)
	uassert.Equal(t, int64(1000), seller)
}

// TestParseIDRejectsGarbage guards the v5 record shrinking: ids now live as
// int64, so anything that is not a positive decimal must be refused at the
// door instead of silently becoming 0.
func TestParseIDRejectsGarbage(cur realm, t *testing.T) {
	uassert.Equal(t, int64(7), parseID("7", "token id"))

	uassert.PanicsWithMessage(t, cur, "invalid token id: 0", func() {
		parseID("0", "token id")
	})
	uassert.PanicsWithMessage(t, cur, "invalid collection id: x1", func() {
		parseID("x1", "collection id")
	})
}

func TestPadIDSortsNumerically(t *testing.T) {
	uassert.Equal(t, "000000000002", padID(2))
	uassert.Equal(t, "000000000010", padID(10))
	uassert.True(t, padID(2) < padID(10))
}

// TestToInfoKeepsStringWireFormat: records shrank to int64 internally, but the
// exported view must still speak the exact same strings the frontend decoder
// expects, in the same field order.
func TestToInfoKeepsStringWireFormat(t *testing.T) {
	seller := testutils.TestAddress("seller")
	info := toInfo(&Listing{id: 2, collectionID: 3, tokenID: 11, seller: seller, priceUgnot: 5_000_000, active: true, createdAt: 42})
	uassert.Equal(t, "2", info.ID)
	uassert.Equal(t, "3", info.CollectionID)
	uassert.Equal(t, "11", info.TokenID)
	uassert.Equal(t, seller, info.Seller)
	uassert.Equal(t, int64(5_000_000), info.PriceUgnot)
	uassert.True(t, info.Active)
	uassert.Equal(t, int64(42), info.CreatedAt)
}

// TestIndexLifecycle checks that a listing enters every index it should and
// leaves all of them on deactivate, so ListActive can never serve a sold item.
func TestIndexLifecycle(t *testing.T) {
	seller := testutils.TestAddress("seller2")
	l := &Listing{id: 5, collectionID: 1, tokenID: 4, seller: seller, priceUgnot: 1000, active: true}
	listings.Set(padID(l.id), l)
	byToken.Set("1:4", l.id)
	indexActive(l)

	uassert.Equal(t, int64(1), activeCount)
	uassert.Equal(t, "5", ListingForToken("1", "4").ID)
	uassert.Equal(t, 1, len(ListActive(0, 10)))
	uassert.Equal(t, 1, len(ListBySeller(seller, 0, 10)))
	uassert.Equal(t, 1, len(ListByCollection("1", 0, 10)))
	uassert.Equal(t, int64(1000), FloorPrice("1"))

	deactivate(l)

	uassert.Equal(t, int64(0), activeCount)
	uassert.Equal(t, "", ListingForToken("1", "4").ID)
	uassert.Equal(t, 0, len(ListActive(0, 10)))
	uassert.Equal(t, 0, len(ListBySeller(seller, 0, 10)))
	uassert.Equal(t, int64(0), FloorPrice("1"))
	listings.Remove(padID(5))
}

package nftoffers57

import "gno.land/p/nt/avl/v0"

// avlGet is the ONE place where this package touches avl.Tree.Get.
//
// The avl/v0 published on gno.land returns (value, exists); the one
// shipped with the pearl testnet's GNOROOT returns a single value. Every
// other line of this package is identical on both networks, so the whole
// difference is isolated here instead of being spread over every call
// site. Switch it with: python3 scripts/avl-shim.py <pearl|mainnet>
//
// AVL-VARIANT: pearl
func avlGet(t *avl.Tree, key string) any {
	return t.Get(key)
}

package nftoffers57

import (
	"testing"

	"chain/runtime"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

// v5.7 dropped byToken/byBuyer/byCollection and answers every read from the
// single byExpiry index. Same rule as the marketplace: the cheaper shape is
// only acceptable if the answers are identical. The cases most likely to
// break are collection 1 picking up collection 11's bids, collection-wide
// bids being mixed into a token's own bid list, and an expired bid being
// presented as acceptable.

func addTestOffer(id, cid, tid int64, buyer address, amount, expiresAt int64) *Offer {
	o := &Offer{
		id: id, collectionID: cid, tokenID: tid, buyer: buyer,
		amountUgnot: amount, active: true, expiresAtHeight: expiresAt,
	}
	offers.Set(padID(o.id), o)
	indexActive(o)
	return o
}

func dropTestOffer(o *Offer) {
	if o.active {
		deactivate(o)
	}
	offers.Remove(padID(o.id))
}

func live() int64 { return runtime.ChainHeight() + 1_000_000 }

// TestOffersForTokenIsExact keeps the token bid list honest: only bids
// addressed to THAT token of THAT collection.
func TestOffersForTokenIsExact(t *testing.T) {
	buyer := testutils.TestAddress("ibuyer")

	mine := addTestOffer(201, 1, 2, buyer, 500, live())
	defer dropTestOffer(mine)
	otherToken := addTestOffer(202, 1, 3, buyer, 600, live())
	defer dropTestOffer(otherToken)
	// Collection 11, token 2: a string-prefix rewrite would leak this.
	neighbour := addTestOffer(203, 11, 2, buyer, 700, live())
	defer dropTestOffer(neighbour)
	// A collection-wide bid is not "addressed to" token 2.
	wide := addTestOffer(204, 1, 0, buyer, 800, live())
	defer dropTestOffer(wide)

	got := OffersForToken("1", "2")
	uassert.Equal(t, 1, len(got))
	uassert.Equal(t, "201", got[0].ID)

	gotNeighbour := OffersForToken("11", "2")
	uassert.Equal(t, 1, len(gotNeighbour))
	uassert.Equal(t, "203", gotNeighbour[0].ID)

	uassert.Equal(t, 0, len(OffersForToken("1", "99")))
}

// TestCollectionOffersIncludesWideBids: a collection page must show the
// collection-wide bids too, because those are real money any holder can take.
func TestCollectionOffersIncludesWideBids(t *testing.T) {
	buyer := testutils.TestAddress("ibuyer2")

	a := addTestOffer(211, 1, 1, buyer, 100, live())
	defer dropTestOffer(a)
	b := addTestOffer(212, 1, 0, buyer, 200, live())
	defer dropTestOffer(b)
	c := addTestOffer(213, 11, 1, buyer, 300, live())
	defer dropTestOffer(c)

	got := CollectionOffers("1", 0, 10)
	uassert.Equal(t, 2, len(got))
	for _, o := range got {
		uassert.Equal(t, "1", o.CollectionID)
	}
	uassert.Equal(t, 1, len(CollectionOffers("11", 0, 10)))
	uassert.Equal(t, 0, len(CollectionOffers("5", 0, 10)))
}

// TestOffersByBuyerFiltersAndPages covers the "my bids" view, which is how a
// buyer finds where their escrowed GNOT is locked. Interleaved noise proves
// the filtered offset does not drift.
func TestOffersByBuyerFiltersAndPages(t *testing.T) {
	me := testutils.TestAddress("mybids")
	other := testutils.TestAddress("otherbids")

	a := addTestOffer(221, 1, 1, me, 100, live())
	defer dropTestOffer(a)
	n1 := addTestOffer(222, 1, 2, other, 100, live())
	defer dropTestOffer(n1)
	b := addTestOffer(223, 2, 1, me, 200, live())
	defer dropTestOffer(b)
	n2 := addTestOffer(224, 2, 2, other, 100, live())
	defer dropTestOffer(n2)
	c := addTestOffer(225, 3, 1, me, 300, live())
	defer dropTestOffer(c)

	uassert.Equal(t, 3, len(OffersByBuyer(me, 0, 0)))
	uassert.Equal(t, 2, len(OffersByBuyer(other, 0, 0)))

	first := OffersByBuyer(me, 0, 2)
	second := OffersByBuyer(me, 2, 2)
	uassert.Equal(t, 2, len(first))
	uassert.Equal(t, 1, len(second))

	seen := map[string]bool{}
	for _, o := range first {
		seen[o.ID] = true
	}
	for _, o := range second {
		uassert.False(t, seen[o.ID])
		seen[o.ID] = true
	}
	uassert.Equal(t, 3, len(seen))
	uassert.Equal(t, 0, len(OffersByBuyer(me, 3, 2)))
}

// TestBestOfferForTokenPicksTheRealBest is the read a holder actually acts
// on, so it has to consider token-specific AND collection-wide bids, ignore
// expired escrow, and never cross collections.
func TestBestOfferForTokenPicksTheRealBest(t *testing.T) {
	buyer := testutils.TestAddress("bestbuyer")

	lowSpecific := addTestOffer(231, 1, 1, buyer, 1_000, live())
	defer dropTestOffer(lowSpecific)
	highWide := addTestOffer(232, 1, 0, buyer, 5_000, live())
	defer dropTestOffer(highWide)
	expiredHuge := addTestOffer(233, 1, 1, buyer, 99_000, 1)
	defer dropTestOffer(expiredHuge)
	otherCollection := addTestOffer(234, 11, 1, buyer, 50_000, live())
	defer dropTestOffer(otherCollection)
	otherToken := addTestOffer(235, 1, 2, buyer, 7_000, live())
	defer dropTestOffer(otherToken)

	best := BestOfferForToken("1", "1")
	uassert.Equal(t, "232", best.ID)
	uassert.Equal(t, int64(5_000), best.AmountUgnot)

	// Token 2 can take its own 7_000 bid, which beats the 5_000 wide one.
	uassert.Equal(t, "235", BestOfferForToken("1", "2").ID)

	// A token in a collection with no live bids reports nothing.
	uassert.Equal(t, "", BestOfferForToken("5", "1").ID)

	// Closing the wide bid falls back to the token's own live bid, never to
	// the expired one.
	deactivate(highWide)
	uassert.Equal(t, "231", BestOfferForToken("1", "1").ID)
}

// TestClosingAnOfferRemovesItFromEveryRead: with one index, a single removal
// must clear the offer from all reads AND from the sweep queue. Escrow that
// lingered in the sweep queue after being paid out would be a double spend.
func TestClosingAnOfferRemovesItFromEveryRead(t *testing.T) {
	buyer := testutils.TestAddress("closerbid")
	o := addTestOffer(241, 6, 3, buyer, 4_000, live())
	defer dropTestOffer(o)

	uassert.Equal(t, 1, len(OffersForToken("6", "3")))
	uassert.Equal(t, 1, len(OffersByBuyer(buyer, 0, 10)))
	uassert.Equal(t, 1, len(CollectionOffers("6", 0, 10)))
	uassert.Equal(t, "241", BestOfferForToken("6", "3").ID)

	before := activeCount
	deactivate(o)

	uassert.Equal(t, before-1, activeCount)
	uassert.Equal(t, 0, len(OffersForToken("6", "3")))
	uassert.Equal(t, 0, len(OffersByBuyer(buyer, 0, 10)))
	uassert.Equal(t, 0, len(CollectionOffers("6", 0, 10)))
	uassert.Equal(t, "", BestOfferForToken("6", "3").ID)

	// The record survives as history, marked closed.
	uassert.Equal(t, "241", GetOffer("241").ID)
	uassert.False(t, GetOffer("241").Active)
}

// TestExpiredOfferIsStillSweepableButNotAcceptable pins the distinction the
// single index has to keep straight: expired escrow must stay IN the sweep
// queue (so the buyer gets refunded) while being invisible to a holder
// looking for a bid to accept.
func TestExpiredOfferIsStillSweepableButNotAcceptable(t *testing.T) {
	buyer := testutils.TestAddress("rotten")
	o := addTestOffer(251, 7, 1, buyer, 3_000, 1)
	defer dropTestOffer(o)

	uassert.Equal(t, "", BestOfferForToken("7", "1").ID)
	uassert.True(t, ExpiredOfferCount() >= 1)
	// It is still listed as an active (funded) offer, because the money is
	// genuinely still locked until someone sweeps it.
	uassert.Equal(t, 1, len(OffersByBuyer(buyer, 0, 10)))
}

// Package nftoffers57 is the v5 escrowed offer (bid) book for collections
// minted through gno.land/r/g1hx4z2.../nft57.
//
// An offer locks the buyer's GNOT in this realm until the offer is
// accepted, cancelled, rejected, or swept after expiry. Money never sits
// anywhere a human has to be trusted.
//
// WHAT CHANGED VS V4 (gno.land/r/g1hx4z2.../nftoffers4)
//
//  1. RejectOffer - the seller side of the book finally exists. In v4 an
//     owner who disliked a lowball bid could do nothing: only the buyer
//     could cancel, so the bid sat on the token's page until it expired.
//     Now the current owner of the token can reject it, which refunds the
//     buyer immediately. Only token-specific offers are rejectable;
//     collection-wide offers have no single owner with standing to reject
//     them, and letting any holder kill them would be a griefing vector.
//
//  2. SweepExpired - expired escrow is no longer stuck. v4 checked expiry
//     when accepting, but nothing ever refunded an expired offer, so the
//     buyer's coins stayed locked until they remembered to cancel. Sweeping
//     is permissionless (anyone may pay the gas; funds only ever go back to
//     the original buyer) and driven by a byExpiry index, so it costs one
//     ordered walk instead of a full scan.
//
//  3. Records are roughly half the size, same change as nftmarket57:
//     ids/amounts/heights are int64 internally and the index trees hold
//     int64 values instead of duplicated strings. OfferInfo still exports
//     strings, so the frontend decoder only needs a new pkgpath.
//
//  4. ONE index instead of four (v5.7). byToken, byBuyer and
//     byCollection were duplicates of what byExpiry already holds:
//     byExpiry must contain every active offer of both kinds, otherwise
//     expired escrow could not be swept. So the three prefix trees are
//     gone and every read is a filtered walk over byExpiry. A funded
//     offer now writes two AVL nodes instead of five, and closing one
//     removes one instead of four.
//
//     Escrow safety is deliberately untouched: the index that got to stay
//     is precisely the one that guarantees a buyer's coins can always be
//     refunded. And no read moved off chain - the book still answers from
//     chain state, so it survives the indexer being down. The cost is
//     that per-buyer and per-collection reads scan the ACTIVE book
//     (bounded by live offers, not by history) and come back ordered by
//     expiry height instead of by offer id.
//
// Kept from v4 deliberately: authorization via cur.Previous().Address(),
// assertDirectPayment on the funding path, deactivate-before-payout
// ordering, and active-only pagination.
package nftoffers57

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/nt/avl/v0"
	"gno.land/r/g1hx4z2kwrnzd9up3g0gd4hspc6v78e4r90jkke3/nft57"
)

// MaxExpiryBlocks caps how long escrow can be locked (~30 days at 1s
// blocks), so a forgotten offer cannot hold coins hostage forever.
const MaxExpiryBlocks = 2_592_000

// MaxSweepLimit bounds one SweepExpired call so it can never run past the
// block gas limit no matter how many offers expired at once.
const MaxSweepLimit = 50

// Offer is one escrowed bid. tokenID == 0 means a collection-wide offer:
// it can be accepted by the owner of any token in that collection.
type Offer struct {
	id              int64
	collectionID    int64
	tokenID         int64
	buyer           address
	amountUgnot     int64
	active          bool
	expiresAtHeight int64
	createdAt       int64
}

// OfferInfo is the exported, read-only view of an Offer. IDs stay strings
// so existing frontend decoders keep working untouched; a collection-wide
// offer reports TokenID "".
type OfferInfo struct {
	ID              string
	CollectionID    string
	TokenID         string
	Buyer           address
	AmountUgnot     int64
	Active          bool
	ExpiresAtHeight int64
	CreatedAt       int64
}

var (
	offers = avl.NewTree() // paddedOfferID -> *Offer (active and closed)
	// byExpiry is the ONLY live index: "paddedHeight:paddedOfferID" ->
	// int64 offer id, active offers exclusively, ordered by expiry height.
	// It drives SweepExpired (that ordering is why expired escrow is
	// always refundable) and, since it necessarily holds every active
	// offer, it is also the universe every read walks.
	byExpiry    = avl.NewTree()
	nextID      int64
	activeCount int64
)

// assertDirectPayment rejects any call path where the tx's coin envelope
// cannot be trusted to have actually landed in this realm.
//
// IsUserCall() is true only when the previous frame is an EOA calling this
// function directly ("gnokey maketx call" / a wallet): its pkgPath is empty.
// Every code realm has a non-empty pkgPath, and MsgRun executes inside the
// ephemeral /e/<addr>/run realm, so both paths are rejected here.
//
// runtime.AssertOriginCall() is deliberately NOT used: under the crossing
// model it can never pass for a "cur realm" function, not even for a
// legitimate direct wallet call.
func assertDirectPayment(cur realm) {
	if !cur.Previous().IsUserCall() {
		panic("this function must be called directly by a wallet, not through another realm")
	}
}

// MakeOffer escrows the sent GNOT as a bid. Pass an empty tokenID to bid
// on any token of the collection. expiresInBlocks must be positive and at
// most MaxExpiryBlocks.
func MakeOffer(cur realm, collectionID, tokenID string, expiresInBlocks int64) string {
	assertDirectPayment(cur)
	caller := cur.Previous().Address()

	amount := unsafe.OriginSend().AmountOf("ugnot")
	if amount <= 0 {
		panic("an offer must be funded: send ugnot with this call")
	}
	if expiresInBlocks <= 0 || expiresInBlocks > MaxExpiryBlocks {
		panic("expiresInBlocks must be between 1 and " + strconv.FormatInt(MaxExpiryBlocks, 10))
	}

	cid := parseID(collectionID, "collection id")
	var tid int64
	if tokenID != "" {
		tid = parseID(tokenID, "token id")
		owner, err := nft57.OwnerOf(collectionID, tokenID)
		if err != nil {
			panic(err)
		}
		if owner == caller {
			panic("cannot bid on a token you already own")
		}
	}

	nextID++
	o := &Offer{
		id:              nextID,
		collectionID:    cid,
		tokenID:         tid,
		buyer:           caller,
		amountUgnot:     amount,
		active:          true,
		expiresAtHeight: runtime.ChainHeight() + expiresInBlocks,
		createdAt:       runtime.ChainHeight(),
	}
	offers.Set(padID(o.id), o)
	indexActive(o)

	id := strconv.FormatInt(o.id, 10)
	chain.Emit(
		"OfferMade",
		"offerId", id,
		"collection", collectionID,
		"tokenId", tokenID,
		"buyer", caller.String(),
		"amount", strconv.FormatInt(amount, 10),
		"expiresAt", strconv.FormatInt(o.expiresAtHeight, 10),
	)

	return id
}

// CancelOffer withdraws an active offer and refunds its escrow. Buyer only.
func CancelOffer(cur realm, offerID string) {
	caller := cur.Previous().Address()
	o := mustGetOffer(offerID)
	if !o.active {
		panic("offer is not active")
	}
	if o.buyer != caller {
		panic("only the buyer can cancel this offer")
	}

	deactivate(o)
	refund(cur, o)
	chain.Emit("OfferCancelled", "offerId", offerID, "refunded", strconv.FormatInt(o.amountUgnot, 10))
}

// RejectOffer lets the CURRENT OWNER of a token turn down a bid on it,
// refunding the buyer immediately instead of leaving the bid parked on
// the token's page until it expires. New in v5.
//
// Only token-specific offers can be rejected: a collection-wide offer is
// addressed to every holder at once, so no single holder has standing to
// kill it for everyone else.
func RejectOffer(cur realm, offerID string) {
	caller := cur.Previous().Address()
	o := mustGetOffer(offerID)
	if !o.active {
		panic("offer is not active")
	}
	if o.tokenID == 0 {
		panic("collection-wide offers cannot be rejected; they are not addressed to a single owner")
	}

	collectionID := strconv.FormatInt(o.collectionID, 10)
	tokenID := strconv.FormatInt(o.tokenID, 10)
	owner, err := nft57.OwnerOf(collectionID, tokenID)
	if err != nil {
		panic(err)
	}
	if owner != caller {
		panic("only the current owner of the token can reject this offer")
	}

	deactivate(o)
	refund(cur, o)

	chain.Emit(
		"OfferRejected",
		"offerId", offerID,
		"collection", collectionID,
		"tokenId", tokenID,
		"by", caller.String(),
		"refunded", strconv.FormatInt(o.amountUgnot, 10),
	)
}

// SweepExpired refunds up to limit expired offers and closes them. New in
// v5, and deliberately permissionless: escrow only ever goes back to the
// original buyer, so the worst a caller can do is pay gas on someone
// else's behalf. limit is clamped to MaxSweepLimit; pass 0 for the max.
//
// It walks byExpiry, which is ordered by expiry height, so it stops at the
// first offer that is still alive instead of scanning the whole book.
func SweepExpired(cur realm, limit int64) int64 {
	if limit <= 0 || limit > MaxSweepLimit {
		limit = MaxSweepLimit
	}
	height := runtime.ChainHeight()

	// Collect first: mutating the tree while iterating it is not safe.
	expired := make([]*Offer, 0, limit)
	byExpiry.Iterate("", "", func(key string, value any) bool {
		if int64(len(expired)) >= limit {
			return true
		}
		o := getOffer(value.(int64))
		if o == nil || !o.active {
			return false
		}
		if o.expiresAtHeight > height {
			// Ordered by expiry: everything after this is still alive.
			return true
		}
		expired = append(expired, o)
		return false
	})

	var swept int64
	for _, o := range expired {
		deactivate(o)
		refund(cur, o)
		swept++
		chain.Emit(
			"OfferExpired",
			"offerId", strconv.FormatInt(o.id, 10),
			"buyer", o.buyer.String(),
			"refunded", strconv.FormatInt(o.amountUgnot, 10),
		)
	}
	if swept > 0 {
		chain.Emit("OffersSwept", "count", strconv.FormatInt(swept, 10))
	}
	return swept
}

// ExpiredOfferCount reports how many active offers are already past their
// expiry height, so a UI (or a cron) knows whether sweeping is worth it.
func ExpiredOfferCount() int64 {
	height := runtime.ChainHeight()
	var n int64
	byExpiry.Iterate("", "", func(key string, value any) bool {
		o := getOffer(value.(int64))
		if o == nil || !o.active {
			return false
		}
		if o.expiresAtHeight > height {
			return true
		}
		n++
		return false
	})
	return n
}

// AcceptOffer sells a token to the bidder. The caller must own the token
// and must have approved this realm on nft57. For a collection-wide offer,
// tokenID selects which token is being sold; for a token-specific offer it
// must match (or be left empty).
func AcceptOffer(cur realm, offerID, tokenID string) {
	caller := cur.Previous().Address()
	o := mustGetOffer(offerID)
	if !o.active {
		panic("offer is not active")
	}
	if runtime.ChainHeight() > o.expiresAtHeight {
		panic("offer has expired")
	}
	if o.buyer == caller {
		panic("cannot accept your own offer")
	}

	collectionID := strconv.FormatInt(o.collectionID, 10)
	tid := resolveToken(o, tokenID)

	owner, err := nft57.OwnerOf(collectionID, tid)
	if err != nil {
		panic(err)
	}
	if owner != caller {
		panic("only the token owner can accept an offer on it")
	}
	offerAddr := cur.Address()
	approved, _ := nft57.GetApproved(collectionID, tid)
	if approved != offerAddr && !nft57.IsApprovedForAll(collectionID, owner, offerAddr) {
		panic("offers realm is not approved to transfer this token yet; call nft57.Approve or nft57.SetApprovalForAll first")
	}

	// Deactivate first, then move money.
	deactivate(o)

	royaltyAddr, rawRoyalty, err := nft57.RoyaltyInfo(collectionID, tid, o.amountUgnot)
	if err != nil {
		rawRoyalty = 0
	}
	royaltyAmt, sellerAmt := splitPayment(o.amountUgnot, rawRoyalty, royaltyAddr == caller)

	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	if royaltyAmt > 0 {
		bk.SendCoins(offerAddr, royaltyAddr, chain.NewCoins(chain.NewCoin("ugnot", royaltyAmt)))
	}
	bk.SendCoins(offerAddr, caller, chain.NewCoins(chain.NewCoin("ugnot", sellerAmt)))

	// Cross into nft57 to move ownership. Reverts the whole tx, transfers
	// included, if approval no longer stands.
	nft57.TransferFrom(cross(cur), collectionID, tid, caller, o.buyer)

	chain.Emit(
		"OfferAccepted",
		"offerId", offerID,
		"collection", collectionID,
		"tokenId", tid,
		"seller", caller.String(),
		"buyer", o.buyer.String(),
		"amount", strconv.FormatInt(o.amountUgnot, 10),
		"royalty", strconv.FormatInt(royaltyAmt, 10),
	)
}

// splitPayment is the pure payout arithmetic, kept separate so it can be
// unit-tested without a funded chain: a royalty is only honoured when it
// is positive, strictly smaller than the bid, and not payable to the
// seller themselves.
func splitPayment(amount, royalty int64, royaltyGoesToSeller bool) (royaltyAmt, sellerAmt int64) {
	if royalty <= 0 || royalty >= amount || royaltyGoesToSeller {
		royalty = 0
	}
	return royalty, amount - royalty
}

// Read-only views.

// GetOffer returns one offer by ID.
func GetOffer(offerID string) OfferInfo { return toInfo(mustGetOffer(offerID)) }

// OffersForToken returns every active offer addressed to one token. Note
// this means token-SPECIFIC offers only, exactly as before: a
// collection-wide bid is not "addressed to" a token. Use BestOfferForToken
// to see what a holder could actually accept.
func OffersForToken(collectionID, tokenID string) []OfferInfo {
	cid := parseID(collectionID, "collection id")
	tid := parseID(tokenID, "token id")
	return collectActive(func(o *Offer) bool {
		return o.collectionID == cid && o.tokenID == tid
	}, 0, 0)
}

// OffersByBuyer returns a page of one buyer's active offers - the "my bids"
// view a buyer needs to find what their money is currently locked in.
func OffersByBuyer(buyer address, offset, limit int64) []OfferInfo {
	return collectActive(func(o *Offer) bool { return o.buyer == buyer }, offset, limit)
}

// CollectionOffers returns a page of a collection's active offers,
// including the collection-wide ones.
func CollectionOffers(collectionID string, offset, limit int64) []OfferInfo {
	cid := parseID(collectionID, "collection id")
	return collectActive(func(o *Offer) bool { return o.collectionID == cid }, offset, limit)
}

// BestOfferForToken returns the highest live bid a token's owner could
// accept right now - token-specific and collection-wide offers together -
// or an empty OfferInfo when there is none.
func BestOfferForToken(collectionID, tokenID string) OfferInfo {
	height := runtime.ChainHeight()
	var best *Offer
	cid := parseID(collectionID, "collection id")
	byExpiry.Iterate("", "", func(key string, value any) bool {
		o := getOffer(value.(int64))
		if o == nil || !o.active || o.expiresAtHeight < height {
			return false
		}
		if o.collectionID != cid {
			return false
		}
		if o.tokenID != 0 && strconv.FormatInt(o.tokenID, 10) != tokenID {
			return false
		}
		if best == nil || o.amountUgnot > best.amountUgnot {
			best = o
		}
		return false
	})
	if best == nil {
		return OfferInfo{}
	}
	return toInfo(best)
}

// OfferCount returns the total number of offers ever made.
func OfferCount() int64 { return nextID }

// ActiveOfferCount returns how many offers are currently active.
func ActiveOfferCount() int64 { return activeCount }

// Render implements the gno.land realm home-page convention.
func Render(path string) string {
	if path != "" {
		o := getOfferByString(path)
		if o == nil {
			return "# 404\n\noffer not found: " + path
		}
		return renderOffer(o)
	}

	out := "# gnoNFT Offers v5\n\n"
	if activeCount == 0 {
		return out + "No active offers.\n"
	}
	out += strconv.FormatInt(activeCount, 10) + " active offer(s), " +
		strconv.FormatInt(ExpiredOfferCount(), 10) + " awaiting sweep\n\n"
	byExpiry.Iterate("", "", func(key string, value any) bool {
		if o := getOffer(value.(int64)); o != nil {
			out += renderOffer(o) + "\n"
		}
		return false
	})
	return out
}

func renderOffer(o *Offer) string {
	target := strconv.FormatInt(o.collectionID, 10) + ":*"
	if o.tokenID != 0 {
		target = strconv.FormatInt(o.collectionID, 10) + ":" + strconv.FormatInt(o.tokenID, 10)
	}
	status := "active"
	if !o.active {
		status = "closed"
	} else if o.expiresAtHeight < runtime.ChainHeight() {
		status = "expired (sweepable)"
	}
	return "- #" + strconv.FormatInt(o.id, 10) + " " + target + " - " +
		strconv.FormatInt(o.amountUgnot, 10) + "ugnot by " + o.buyer.String() +
		" (" + status + ")"
}

// Internal helpers.

func indexActive(o *Offer) {
	byExpiry.Set(padID(o.expiresAtHeight)+":"+padID(o.id), o.id)
	activeCount++
}

func deactivate(o *Offer) {
	o.active = false
	// One removal takes the offer out of the sweep queue and out of every
	// read at the same time, which is exactly why there is only one index.
	byExpiry.Remove(padID(o.expiresAtHeight) + ":" + padID(o.id))
	if activeCount > 0 {
		activeCount--
	}
}

// refund returns an offer's escrow to its buyer. Always call deactivate
// before this so a re-entrant path can never be paid twice.
func refund(cur realm, o *Offer) {
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bk.SendCoins(cur.Address(), o.buyer, chain.NewCoins(chain.NewCoin("ugnot", o.amountUgnot)))
}

// collectActive walks the active book (byExpiry), applies a predicate, and
// returns one page. Offset counts only rows that actually matched, so
// paging a filtered view cannot silently skip offers.
func collectActive(keep func(*Offer) bool, offset, limit int64) []OfferInfo {
	if offset < 0 {
		offset = 0
	}
	if limit < 0 {
		limit = 0
	}
	out := []OfferInfo{}
	var seen int64
	byExpiry.Iterate("", "", func(key string, value any) bool {
		o := getOffer(value.(int64))
		if o == nil || !o.active {
			return false
		}
		if keep != nil && !keep(o) {
			return false
		}
		if seen < offset {
			seen++
			return false
		}
		if limit > 0 && int64(len(out)) >= limit {
			return true
		}
		out = append(out, toInfo(o))
		seen++
		return false
	})
	return out
}

// resolveToken decides which token an AcceptOffer call is about: for a
// token-specific offer the argument must match or be empty; for a
// collection-wide offer it is required.
func resolveToken(o *Offer, tokenID string) string {
	if o.tokenID != 0 {
		own := strconv.FormatInt(o.tokenID, 10)
		if tokenID != "" && tokenID != own {
			panic("this offer is for token " + own + ", not " + tokenID)
		}
		return own
	}
	if tokenID == "" {
		panic("this is a collection-wide offer: pass the tokenID you want to sell")
	}
	parseID(tokenID, "token id")
	return tokenID
}

// padID zero-pads a number so index trees sort numerically rather than
// lexicographically ("10" must come after "2"). Also used for expiry
// heights, which is what makes the byExpiry walk ordered.
func padID(id int64) string {
	const width = 12
	s := strconv.FormatInt(id, 10)
	if len(s) >= width {
		return s
	}
	return "000000000000"[:width-len(s)] + s
}

// parseID rejects anything that is not a positive decimal integer, so a
// malformed id can never be written into a record or an index key.
func parseID(s, what string) int64 {
	v, err := strconv.ParseInt(s, 10, 64)
	if err != nil || v <= 0 {
		panic("invalid " + what + ": " + s)
	}
	return v
}

func toInfo(o *Offer) OfferInfo {
	tokenID := ""
	if o.tokenID != 0 {
		tokenID = strconv.FormatInt(o.tokenID, 10)
	}
	return OfferInfo{
		ID:              strconv.FormatInt(o.id, 10),
		CollectionID:    strconv.FormatInt(o.collectionID, 10),
		TokenID:         tokenID,
		Buyer:           o.buyer,
		AmountUgnot:     o.amountUgnot,
		Active:          o.active,
		ExpiresAtHeight: o.expiresAtHeight,
		CreatedAt:       o.createdAt,
	}
}

func getOffer(id int64) *Offer {
	v := avlGet(offers, padID(id))
	if v == nil {
		return nil
	}
	return v.(*Offer)
}

func getOfferByString(id string) *Offer {
	v, err := strconv.ParseInt(id, 10, 64)
	if err != nil {
		return nil
	}
	return getOffer(v)
}

func mustGetOffer(id string) *Offer {
	o := getOfferByString(id)
	if o == nil {
		panic("offer not found: " + id)
	}
	return o
}

package nftoffers57

import (
	"strconv"
	"testing"

	"chain/runtime"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

// NOTE: MakeOffer/AcceptOffer/CancelOffer/RejectOffer/SweepExpired move real
// escrowed coins and are gated on a direct wallet MsgCall, so the money paths
// are verified on-chain on Pearl. Everything that does not require a funded
// chain (payout split, expiry selection, index keys, id parsing, the
// collection-wide rejection rule) is factored out and tested here.

func TestSplitPayment(t *testing.T) {
	// Royalty comes out of the escrowed amount.
	royalty, seller := splitPayment(1000, 50, false)
	uassert.Equal(t, int64(50), royalty)
	uassert.Equal(t, int64(950), seller)

	// No royalty when the creator is the one selling.
	royalty, seller = splitPayment(1000, 50, true)
	uassert.Equal(t, int64(0), royalty)
	uassert.Equal(t, int64(1000), seller)

	// A royalty at or above the amount is ignored rather than zeroing the seller.
	royalty, seller = splitPayment(1000, 1000, false)
	uassert.Equal(t, int64(0), royalty)
	uassert.Equal(t, int64(1000), seller)

	// The split always conserves the escrow.
	royalty, seller = splitPayment(7777, 13, false)
	uassert.Equal(t, int64(7777), royalty+seller)
}

// TestResolveToken covers collection-wide offers: a token-specific offer stays
// pinned to its token, while a collection-wide bid requires the accepting
// holder to name which token they are selling.
func TestResolveToken(cur realm, t *testing.T) {
	tokenOffer := &Offer{id: 1, collectionID: 1, tokenID: 7}
	collOffer := &Offer{id: 2, collectionID: 1, tokenID: 0}

	uassert.Equal(t, "7", resolveToken(tokenOffer, ""))
	uassert.Equal(t, "7", resolveToken(tokenOffer, "7"))
	uassert.Equal(t, "3", resolveToken(collOffer, "3"))

	uassert.PanicsWithMessage(t, cur, "this offer is for token 7, not 9", func() {
		resolveToken(tokenOffer, "9")
	})
	uassert.PanicsWithMessage(t, cur, "this is a collection-wide offer: pass the tokenID you want to sell", func() {
		resolveToken(collOffer, "")
	})
}

// TestParseIDRejectsGarbage guards the v5 record shrinking: ids now live as
// int64, so anything that is not a positive decimal must be refused at the
// door instead of silently becoming 0.
func TestParseIDRejectsGarbage(cur realm, t *testing.T) {
	uassert.Equal(t, int64(12), parseID("12", "token id"))

	uassert.PanicsWithMessage(t, cur, "invalid token id: 0", func() {
		parseID("0", "token id")
	})
	uassert.PanicsWithMessage(t, cur, "invalid token id: -3", func() {
		parseID("-3", "token id")
	})
	uassert.PanicsWithMessage(t, cur, "invalid collection id: abc", func() {
		parseID("abc", "collection id")
	})
}

// TestPadIDSortsNumerically is why the indexes use padded keys: without
// padding "10" would sort before "2" and pagination would jump around.
func TestPadIDSortsNumerically(t *testing.T) {
	uassert.Equal(t, "000000000002", padID(2))
	uassert.Equal(t, "000000000010", padID(10))
	uassert.True(t, padID(2) < padID(10))
	uassert.True(t, padID(999) < padID(1000))
}

// TestToInfoKeepsStringWireFormat: records shrank to int64 internally, but the
// exported view must still speak the exact same strings the frontend decoder
// expects, with "" for a collection-wide offer's token.
func TestToInfoKeepsStringWireFormat(t *testing.T) {
	info := toInfo(&Offer{id: 3, collectionID: 4, tokenID: 9, amountUgnot: 500, active: true})
	uassert.Equal(t, "3", info.ID)
	uassert.Equal(t, "4", info.CollectionID)
	uassert.Equal(t, "9", info.TokenID)
	uassert.Equal(t, int64(500), info.AmountUgnot)
	uassert.True(t, info.Active)

	wide := toInfo(&Offer{id: 4, collectionID: 4, tokenID: 0})
	uassert.Equal(t, "", wide.TokenID)
}

// TestExpiryIndexFindsOnlyExpired is the selection half of SweepExpired: the
// byExpiry walk must pick up offers whose deadline has passed and stop at the
// first one that is still alive.
func TestExpiryIndexFindsOnlyExpired(t *testing.T) {
	buyer := testutils.TestAddress("obuyer")
	height := runtime.ChainHeight()

	stale := &Offer{id: 1, collectionID: 1, tokenID: 1, buyer: buyer, amountUgnot: 100, active: true, expiresAtHeight: 1}
	alsoStale := &Offer{id: 2, collectionID: 1, tokenID: 2, buyer: buyer, amountUgnot: 200, active: true, expiresAtHeight: height}
	live := &Offer{id: 3, collectionID: 1, tokenID: 3, buyer: buyer, amountUgnot: 300, active: true, expiresAtHeight: height + 1_000_000}

	for _, o := range []*Offer{stale, alsoStale, live} {
		offers.Set(padID(o.id), o)
		indexActive(o)
	}

	// An offer expiring exactly at the current height is sweepable.
	uassert.Equal(t, int64(2), ExpiredOfferCount())

	// Closing one removes it from every index, including byExpiry.
	deactivate(stale)
	uassert.Equal(t, int64(1), ExpiredOfferCount())
	uassert.Equal(t, int64(2), activeCount)

	// The live offer is never picked up.
	deactivate(alsoStale)
	uassert.Equal(t, int64(0), ExpiredOfferCount())
	uassert.True(t, live.active)

	deactivate(live)
	uassert.Equal(t, int64(0), activeCount)
	offers.Remove(padID(1))
	offers.Remove(padID(2))
	offers.Remove(padID(3))
}

// TestSweepLimitIsClamped keeps one sweep inside the block gas limit no matter
// how many offers rotted at once.
func TestSweepLimitIsClamped(t *testing.T) {
	uassert.Equal(t, "50", strconv.FormatInt(int64(MaxSweepLimit), 10))
}

// TestRejectRefusesCollectionWideOffers: a collection-wide bid is addressed to
// every holder at once, so no single holder may kill it for everyone else.
func TestRejectRefusesCollectionWideOffers(cur realm, t *testing.T) {
	buyer := testutils.TestAddress("obuyer2")
	wide := &Offer{id: 90, collectionID: 1, tokenID: 0, buyer: buyer, amountUgnot: 100, active: true, expiresAtHeight: runtime.ChainHeight() + 1000}
	offers.Set(padID(wide.id), wide)
	indexActive(wide)

	uassert.PanicsWithMessage(t, cur,
		"collection-wide offers cannot be rejected; they are not addressed to a single owner",
		func() {
			RejectOffer(cur, "90")
		})

	// A closed offer cannot be rejected either.
	deactivate(wide)
	uassert.PanicsWithMessage(t, cur, "offer is not active", func() {
		RejectOffer(cur, "90")
	})
	uassert.PanicsWithMessage(t, cur, "offer not found: 12345", func() {
		RejectOffer(cur, "12345")
	})
	offers.Remove(padID(90))
}
